  color-scheme: dark;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: var(--deep); }
body { touch-action: none; user-select: none; }
button, input { font: inherit; }
button { color: inherit; cursor: pointer; border: 0; background: none; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--lime); outline-offset: 3px; }

#app { position: fixed; inset: 0; overflow: hidden; background: radial-gradient(circle at 60% 30%, #0c2a36 0%, #04121a 52%, #02080c 100%); }
#arena { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.fx-vignette { pointer-events: none; position: absolute; inset: 0; z-index: 2; background:
  radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(1, 7, 10, .42) 78%, rgba(1, 6, 9, .78) 100%),
  linear-gradient(180deg, rgba(1, 8, 11, .42), transparent 18%, transparent 75%, rgba(1, 7, 10, .5));
}
.fx-grain { pointer-events: none; position: absolute; inset: 0; z-index: 3; opacity: .12; mix-blend-mode: overlay; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E"); }

.ui-layer { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.ui-layer button, .ui-layer input, .screen, .modal-layer { pointer-events: auto; }
.screen { position: absolute; inset: 0; }
.is-hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

/* boot */
.boot-screen { position: absolute; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; background: #030c11; transition: opacity .6s ease, visibility .6s; }
.boot-screen.done { opacity: 0; visibility: hidden; }
.boot-mark { display: flex; align-items: center; gap: 14px; font-family: 'Rajdhani', sans-serif; font-size: 42px; font-weight: 700; letter-spacing: .18em; }
.boot-ball { width: 42px; height: 42px; border-radius: 50%; background: conic-gradient(from 20deg, var(--lime) 0 12%, #0a1b22 12% 24%, var(--lime) 24% 38%, #0a1b22 38% 52%, var(--lime) 52% 68%, #0a1b22 68% 82%, var(--lime) 82% 100%); box-shadow: 0 0 34px rgba(217, 255, 67, .3); animation: spin 4s linear infinite; }
.boot-line { width: min(310px, 65vw); height: 2px; background: rgba(255,255,255,.1); overflow: hidden; }
.boot-line i { display: block; width: 45%; height: 100%; background: var(--lime); animation: bootLoad 1.3s ease-in-out infinite; }
.boot-screen p { margin: 0; font-size: 12px; color: var(--muted); letter-spacing: .1em; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes bootLoad { 0% { transform: translateX(220%); } 100% { transform: translateX(-220%); } }

/* top bar */
.topbar { position: absolute; top: 0; left: 0; right: 0; z-index: 30; display: flex; justify-content: space-between; align-items: flex-start; padding: calc(16px + var(--safe-top)) calc(24px + var(--safe-right)) 0 calc(24px + var(--safe-left)); transition: opacity .4s, transform .4s; }
.topbar-left, .topbar-right { display: flex; align-items: center; gap: 10px; min-width: 120px; }
.topbar-right { justify-content: flex-end; }
.mini-logo { width: 40px; height: 40px; display: grid; place-items: center; clip-path: polygon(50% 0, 95% 25%, 88% 75%, 50% 100%, 12% 75%, 5% 25%); background: linear-gradient(150deg, var(--lime), #7ea51a); color: #071119; font: 700 25px/1 'Rajdhani', sans-serif; box-shadow: 0 6px 26px rgba(0,0,0,.3); }
.live-pill { height: 26px; padding: 0 10px; display: flex; align-items: center; gap: 7px; border: 1px solid rgba(255,255,255,.12); background: rgba(4,17,24,.62); border-radius: 3px; font: 600 10px/1 'Rajdhani', sans-serif; letter-spacing: .14em; color: #bad0d3; backdrop-filter: blur(8px); }
.live-pill i, .status-chip i, .online-state i { width: 6px; height: 6px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 9px var(--lime); animation: pulse 1.6s ease-in-out infinite; }
