.icon-btn.muted { color: #6e8288; }

/* score bug */
.scorebug { display: flex; align-items: stretch; height: 62px; min-width: 310px; background: linear-gradient(180deg, rgba(10,31,40,.95), rgba(4,16,22,.92)); border: 1px solid rgba(255,255,255,.12); border-top: 2px solid var(--lime); box-shadow: 0 14px 50px rgba(0,0,0,.38); backdrop-filter: blur(14px); border-radius: 2px 2px 6px 6px; overflow: hidden; }
