.score-code { font: 700 16px/1 'Rajdhani', sans-serif; letter-spacing: .08em; color: #e9f1eb; }
.score-badge { width: 27px; height: 31px; display: grid; place-items: center; clip-path: polygon(50% 0, 94% 19%, 88% 72%, 50% 100%, 12% 72%, 6% 19%); background: var(--home); color: #071119; font: 700 14px/1 'Rajdhani', sans-serif; }
.score-team.away .score-badge { background: var(--away); }
.score-center { width: 116px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: rgba(0,0,0,.24); border-left: 1px solid rgba(255,255,255,.08); border-right: 1px solid rgba(255,255,255,.08); }
.score-numbers { display: flex; align-items: center; gap: 8px; line-height: 1; }
.score-numbers b { font: 700 29px/1 'Rajdhani', sans-serif; color: #fff; letter-spacing: .02em; }
.score-dash { color: #587077; font-size: 18px; }
.score-clock { display: flex; align-items: center; gap: 7px; margin-top: 2px; font: 600 10px/1 'Rajdhani', sans-serif; letter-spacing: .13em; color: var(--lime); }
.score-clock em { font-style: normal; color: #789197; padding-left: 7px; border-left: 1px solid rgba(255,255,255,.16); }

