.status-chip { display: inline-flex; align-items: center; gap: 7px; font: 600 9px/1 'Rajdhani', sans-serif; letter-spacing: .12em; color: #9db4b4; }
.status-chip.offline i { background: var(--coral); box-shadow: 0 0 9px var(--coral); }
.kbd, kbd { display: inline-grid; place-items: center; min-width: 24px; height: 22px; padding: 0 6px; border: 1px solid rgba(255,255,255,.19); background: rgba(0,0,0,.25); border-bottom-width: 2px; border-radius: 3px; font: 600 10px/1 'Rajdhani', sans-serif; letter-spacing: .08em; color: #dbebe6; }

/* ============ MENU ============ */
.menu { display: flex; flex-direction: column; padding: calc(22px + var(--safe-top)) calc(34px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(34px + var(--safe-left)); background: linear-gradient(90deg, rgba(2,10,14,.58) 0%, rgba(2,9,13,.12) 42%, rgba(2,8,12,.62) 100%), linear-gradient(0deg, rgba(2,9,12,.72), transparent 38%); transition: opacity .55s ease, transform .55s ease; }
