@keyframes heroIn { from { opacity: 0; transform: translateY(24px) skewX(-4deg); } }
.hero-sub { color: #a8bcbd; font-size: clamp(12px, 1.12vw, 16px); line-height: 1.85; margin: 20px 0 0; max-width: 360px; border-right: 2px solid var(--lime); padding-right: 15px; }
.hero-stats { display: flex; gap: 0; margin-top: 28px; }
