.hero-stats span { color: #738d91; font-size: 9px; margin-top: 5px; }

.game-panel { width: min(392px, 40vw); background: linear-gradient(155deg, rgba(9,31,39,.88), rgba(4,16,22,.92)); border: 1px solid rgba(177,226,213,.16); border-top: 2px solid rgba(217,255,67,.7); box-shadow: 0 28px 80px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.06); backdrop-filter: blur(18px); padding: 17px 17px 13px; position: relative; overflow: hidden; }
