.arrow-btn:hover { color: var(--lime); border-color: var(--lime); background: rgba(217,255,67,.06); }
.selected-team { display: flex; align-items: center; gap: 13px; margin-top: 10px; background: linear-gradient(105deg, rgba(255,255,255,.055), transparent); padding: 10px 12px 10px 10px; border-right: 2px solid var(--team-accent, var(--lime)); position: relative; }
.team-crest-large { width: 61px; height: 70px; flex: 0 0 auto; display: grid; place-items: center; clip-path: polygon(50% 0, 96% 22%, 88% 74%, 50% 100%, 12% 74%, 4% 22%); background: linear-gradient(155deg, var(--team-color, #d9ff43), var(--team-color2, #1c4d3d)); color: #071116; position: relative; transition: .3s; filter: drop-shadow(0 7px 15px rgba(0,0,0,.28)); }
.team-crest-large span { font: 700 30px/1 'Rajdhani', sans-serif; position: relative; z-index: 2; }
.team-crest-large i { position: absolute; inset: 8px; clip-path: polygon(50% 0, 96% 22%, 88% 74%, 50% 100%, 12% 74%, 4% 22%); border: 1px solid rgba(0,0,0,.3); }
.selected-meta { flex: 1; min-width: 0; }
.selected-city { display: block; font: 600 8px/1 'Rajdhani', sans-serif; color: var(--team-accent, var(--lime)); letter-spacing: .18em; }
.selected-meta h2 { font: 700 25px/1.2 'Cairo', sans-serif; margin: 4px 0 7px; }
.team-tags { display: flex; gap: 5px; flex-wrap: wrap; }
.team-tags span { font-size: 8px; color: #9db0b1; border: 1px solid rgba(255,255,255,.1); padding: 2px 6px; }
.team-overall { display: flex; flex-direction: column; align-items: center; padding-right: 4px; }
.team-overall b { font: 700 30px/1 'Rajdhani', sans-serif; color: #fff; }
.team-overall span { font: 600 8px/1 'Rajdhani', sans-serif; color: #6e858b; letter-spacing: .15em; margin-top: 3px; }
.team-strip { display: flex; gap: 4px; margin-top: 8px; }
.team-dot { flex: 1; height: 24px; position: relative; border: 1px solid transparent; background: rgba(255,255,255,.03); transition: .2s; display: flex; align-items: center; justify-content: center; }
.team-dot i { width: 8px; height: 8px; border-radius: 50%; background: var(--dot); opacity: .55; }
.team-dot.active { border-color: rgba(217,255,67,.6); background: rgba(217,255,67,.08); }
.team-dot.active i { opacity: 1; box-shadow: 0 0 10px var(--dot); }
.team-dot:hover { background: rgba(255,255,255,.08); }

.mode-grid { display: flex; flex-direction: column; gap: 7px; }
.mode-btn { width: 100%; display: flex; align-items: center; gap: 11px; min-height: 57px; padding: 9px 11px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.09); text-align: right; transition: transform .18s, background .18s, border-color .18s; }
.mode-btn:hover { transform: translateX(-3px); border-color: rgba(217,255,67,.5); background: rgba(217,255,67,.07); }
.mode-btn.primary { background: linear-gradient(100deg, var(--lime) 0%, #bde731 100%); color: #071215; border: 0; box-shadow: 0 12px 26px rgba(185, 224, 39, .16); }
.mode-btn.primary:hover { background: linear-gradient(100deg, #e5ff74, #ccf13f); }
.mode-icon { width: 38px; height: 38px; flex: 0 0 auto; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.15); background: rgba(0,0,0,.18); }
.primary .mode-icon { border-color: rgba(0,0,0,.15); background: rgba(0,0,0,.09); }
.mode-icon svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
.primary .mode-icon svg { fill: currentColor; stroke: none; }
.mode-copy { flex: 1; display: flex; flex-direction: column; gap: 2px; }
.mode-copy b { font: 700 15px/1.3 'Cairo', sans-serif; }
.primary .mode-copy b { color: #071215; }
.mode-copy small { font-size: 9px; color: #7f979b; }
.primary .mode-copy small { color: rgba(5,18,24,.58); }
.mode-key, .mode-badge { font: 600 9px/1 'Rajdhani', sans-serif; letter-spacing: .1em; opacity: .55; border: 1px solid currentColor; padding: 4px 5px; }
.primary .mode-key { opacity: .38; color: #071215; }
.mode-badge { color: var(--cyan); opacity: .85; font-size: 8px; }
.panel-footer { display: flex; align-items: center; justify-content: space-between; margin-top: 12px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.08); }
.text-btn { color: #94aaad; font-size: 9px; padding: 2px 0; }
.text-btn:hover { color: var(--lime); }
.panel-note { font: 500 8px/1 'Rajdhani', sans-serif; letter-spacing: .14em; color: #5e777c; }
.menu-footer { display: flex; justify-content: space-between; align-items: center; color: #6b8287; font: 500 9px/1 'Rajdhani', sans-serif; letter-spacing: .12em; border-top: 1px solid rgba(255,255,255,.08); padding-top: 12px; }
.footer-left, .footer-right { display: flex; align-items: center; gap: 9px; }
.footer-left .dot { width: 5px; height: 5px; background: var(--lime); border-radius: 50%; box-shadow: 0 0 7px var(--lime); }
.footer-sep { width: 1px; height: 9px; background: rgba(255,255,255,.16); }
.footer-right span:last-child { opacity: .5; }

/* ============ HUD ============ */
.hud { opacity: 0; visibility: hidden; transition: opacity .3s ease; }
.hud.active { opacity: 1; visibility: visible; }
.event-feed { position: absolute; top: calc(100px + var(--safe-top)); right: calc(24px + var(--safe-right)); display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.feed-item { background: linear-gradient(90deg, transparent, rgba(3,15,20,.72)); border-left: 2px solid var(--lime); padding: 6px 12px; font-size: 10px; color: #c6d7d4; min-width: 190px; text-align: left; animation: feedIn .3s ease both; }
.feed-item b { color: var(--lime); font: 700 10px 'Rajdhani', sans-serif; letter-spacing: .1em; margin-right: 8px; }
@keyframes feedIn { from { opacity: 0; transform: translateX(15px); } }
.hud-bottom { position: absolute; left: calc(26px + var(--safe-left)); right: calc(26px + var(--safe-right)); bottom: calc(20px + var(--safe-bottom)); display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; }
.player-card { display: flex; align-items: center; gap: 10px; height: 53px; padding: 0 13px 0 8px; background: linear-gradient(100deg, rgba(3,15,20,.82), rgba(4,18,24,.4)); border-right: 2px solid var(--lime); backdrop-filter: blur(9px); }
.player-num { width: 36px; height: 37px; display: grid; place-items: center; color: #071216; background: var(--lime); font: 700 22px/1 'Rajdhani', sans-serif; clip-path: polygon(0 0, 100% 0, 100% 78%, 85% 100%, 0 100%); }
.player-info { min-width: 122px; }
.player-info small { display: block; font: 600 8px/1 'Rajdhani', sans-serif; letter-spacing: .14em; color: #7f999c; }
.player-info b { display: block; font: 700 13px/1.5 'Cairo', sans-serif; }
.stamina { width: 100%; height: 3px; background: rgba(255,255,255,.12); margin-top: 3px; }
.stamina i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, var(--cyan), var(--lime)); box-shadow: 0 0 7px rgba(217,255,67,.25); transition: width .15s; }
.charge-wrap { width: 140px; opacity: 0; transform: translateY(8px); transition: .15s; }
.charge-wrap.active { opacity: 1; transform: translateY(0); }
.charge-wrap span { display: block; font: 600 8px/1 'Rajdhani', sans-serif; color: #96aba9; letter-spacing: .18em; margin-bottom: 5px; }
.charge-track { height: 6px; background: rgba(255,255,255,.12); transform: skewX(-18deg); overflow: hidden; }
.charge-track i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--lime) 60%, var(--coral)); box-shadow: 0 0 12px var(--lime); }
.desktop-hints { display: flex; gap: 14px; align-items: center; padding: 10px 14px; background: rgba(3,15,20,.52); backdrop-filter: blur(7px); color: #7c9498; font-size: 8px; }
.desktop-hints span { display: flex; align-items: center; gap: 5px; white-space: nowrap; }
.desktop-hints kbd { min-width: 20px; height: 19px; font-size: 8px; padding: 0 4px; }
.mobile-controls { display: none; }

/* ============ GOAL / COUNTDOWN ============ */
.goal-overlay { position: absolute; inset: 0; z-index: 45; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; pointer-events: none; background: radial-gradient(ellipse at center, rgba(8,24,26,.08), rgba(2,9,12,.62)); }
.goal-overlay.active { opacity: 1; visibility: visible; }
.goal-overlay.flash { animation: goalFlash .6s ease-out; }
@keyframes goalFlash { 0% { background: rgba(217,255,67,.55); } 100% { background: radial-gradient(ellipse at center, rgba(8,24,26,.08), rgba(2,9,12,.62)); } }
.goal-rays { position: absolute; width: 140vmax; height: 140vmax; background: repeating-conic-gradient(from 0deg, rgba(217,255,67,.11) 0deg 4deg, transparent 4deg 13deg); border-radius: 50%; animation: rays 24s linear infinite; mask-image: radial-gradient(circle, #000 0 30%, transparent 65%); }
@keyframes rays { to { transform: rotate(360deg); } }
.goal-content { position: relative; text-align: center; transform: scale(.7) rotate(-2deg); opacity: 0; }
.goal-overlay.active .goal-content { animation: goalPop .65s cubic-bezier(.16,1.4,.3,1) .05s both; }
@keyframes goalPop { to { transform: scale(1) rotate(-2deg); opacity: 1; } }
.goal-kicker { display: block; font: 700 11px/1 'Rajdhani', sans-serif; letter-spacing: .46em; color: var(--lime); margin-bottom: 10px; }
.goal-content h2 { margin: 0; font: 900 clamp(80px, 16vw, 220px)/.7 'Cairo', sans-serif; letter-spacing: -.06em; color: #f4ffdf; text-shadow: 0 0 50px rgba(217,255,67,.35), 0 20px 60px rgba(0,0,0,.4); transform: skewX(-6deg); }
.goal-content h2 span { color: var(--lime); }
.goal-scorer { display: inline-flex; align-items: center; gap: 12px; margin-top: 20px; padding: 8px 16px; background: rgba(4,17,22,.7); border: 1px solid rgba(217,255,67,.28); font-size: 12px; backdrop-filter: blur(10px); }
.goal-scorer span { color: #93aaa9; }
.goal-scorer b { color: var(--lime); font-family: 'Rajdhani', sans-serif; font-size: 17px; letter-spacing: .08em; }
.goal-scorer em { font: 600 11px/1 'Rajdhani', sans-serif; color: #71898d; font-style: normal; padding-right: 10px; border-right: 1px solid rgba(255,255,255,.15); }
.goal-line { width: 170px; height: 2px; background: linear-gradient(90deg, transparent, var(--lime), transparent); margin: 16px auto 0; }
.countdown-overlay { position: absolute; inset: 0; z-index: 40; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; pointer-events: none; opacity: 0; visibility: hidden; }
.countdown-overlay.active { opacity: 1; visibility: visible; }
.countdown-overlay span { font: 700 11px/1 'Rajdhani', sans-serif; letter-spacing: .42em; color: #d8e8e2; }
.countdown-overlay b { font: 700 clamp(90px, 13vw, 160px)/.95 'Rajdhani', sans-serif; color: var(--lime); text-shadow: 0 0 60px rgba(217,255,67,.28); animation: countPop .8s ease both; }
@keyframes countPop { 0% { transform: scale(1.5); opacity: 0; } 30% { opacity: 1; } 100% { transform: scale(.9); opacity: .85; } }

/* ============ MODALS ============ */
.modal-layer { position: absolute; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center; background: rgba(1,8,11,.64); backdrop-filter: blur(9px); opacity: 0; visibility: hidden; transition: opacity .3s, visibility .3s; padding: calc(18px + var(--safe-top)) 18px calc(18px + var(--safe-bottom)); overflow-y: auto; }
.modal-layer.active { opacity: 1; visibility: visible; }
.modal-card { width: min(430px, 100%); background: linear-gradient(150deg, rgba(10,31,39,.98), rgba(4,16,22,.98)); border: 1px solid rgba(185,230,219,.16); border-top: 2px solid var(--lime); padding: 25px 25px 22px; position: relative; box-shadow: 0 30px 100px rgba(0,0,0,.55); animation: modalIn .3s ease both; }
@keyframes modalIn { from { opacity: 0; transform: translateY(12px) scale(.98); } }
.modal-card h2 { font: 700 28px/1.2 'Cairo', sans-serif; margin: 8px 0 8px; }
.modal-card p { color: #8da3a4; font-size: 11px; line-height: 1.8; }
.close-btn { position: absolute; top: 10px; left: 12px; width: 31px; height: 31px; display: grid; place-items: center; color: #8fa5a3; font: 300 24px/1 sans-serif; border: 1px solid rgba(255,255,255,.12); transition: .2s; }
.close-btn:hover { color: var(--lime); border-color: var(--lime); }
.big-btn { width: 100%; min-height: 45px; display: flex; align-items: center; justify-content: center; gap: 9px; font: 700 13px/1 'Cairo', sans-serif; border: 1px solid rgba(255,255,255,.15); transition: transform .16s, background .16s, border-color .16s; }
.big-btn.primary { background: var(--lime); border-color: var(--lime); color: #071215; box-shadow: 0 12px 30px rgba(199,238,48,.12); }
.big-btn.primary:hover { background: #e8ff7f; transform: translateY(-1px); }
.big-btn.ghost { color: #a4b7b6; background: rgba(255,255,255,.03); }
.big-btn.ghost:hover { color: #fff; border-color: rgba(255,255,255,.32); }
.big-btn:disabled { opacity: .35; cursor: not-allowed; transform: none; }
.modal-row { display: flex; gap: 8px; margin-top: 8px; }
.pause-card { text-align: center; }
.pause-card .panel-kicker { color: var(--lime); }
.pause-card h2 { font-size: 36px; margin-top: 12px; }
.pause-card p { margin-bottom: 22px; }
.pause-card .modal-row { margin-top: 8px; }

/* online modal */
.online-card { width: min(450px, 100%); }
.modal-lead { margin-top: 2px; }
.online-tabs { display: flex; border: 1px solid rgba(255,255,255,.12); padding: 3px; margin: 16px 0 14px; }
.online-tab { flex: 1; min-height: 34px; color: #8da3a4; font-size: 11px; transition: .2s; }
.online-tab.active { background: rgba(217,255,67,.11); color: var(--lime); }
.online-pane { display: none; }
.online-pane.active { display: block; }
.room-code-box { display: flex; align-items: center; justify-content: space-between; border: 1px dashed rgba(217,255,67,.35); background: rgba(217,255,67,.04); padding: 9px 13px; }
.room-code-box span { font-size: 9px; color: #7f979a; }
.room-code-box b { font: 700 29px/1 'Rajdhani', sans-serif; letter-spacing: .22em; color: var(--lime); direction: ltr; }
.copy-btn { font-size: 9px; color: var(--lime); border: 1px solid rgba(217,255,67,.3); padding: 5px 8px; }
.online-state { display: flex; align-items: center; gap: 8px; min-height: 28px; font-size: 9px; color: #8fa5a4; margin: 8px 0 12px; }
.online-state.error { color: var(--coral); }
.online-state.error i { background: var(--coral); box-shadow: 0 0 9px var(--coral); animation: none; }
.online-state.ok { color: var(--lime); }
.code-label { display: block; font-size: 9px; color: #8fa5a4; margin-bottom: 6px; }
.code-input { width: 100%; height: 52px; background: rgba(0,0,0,.22); border: 1px solid rgba(255,255,255,.14); color: var(--lime); text-align: center; font: 700 27px/1 'Rajdhani', sans-serif; letter-spacing: .3em; direction: ltr; text-transform: uppercase; }
.code-input:focus { border-color: var(--lime); outline: none; }
.privacy-note { display: block; text-align: center; color: #5e777a; font-size: 8px; margin-top: 10px; }

/* how */
.how-card { width: min(500px, 100%); }
.how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin: 15px 0 12px; }
.how-grid > div { display: grid; grid-template-columns: 37px 1fr; grid-template-rows: auto auto; column-gap: 9px; align-items: center; padding: 8px; background: rgba(255,255,255,.035); border: 1px solid rgba(255,255,255,.06); }
.how-grid kbd { grid-row: span 2; width: 37px; height: 34px; font-size: 10px; }
.how-grid b { font-size: 11px; align-self: end; }
.how-grid span { font-size: 8px; color: #758d90; }
.how-tip { font-size: 9px; color: #91a5a6; padding: 10px 12px; border-right: 2px solid var(--cyan); background: rgba(71,242,208,.04); margin-bottom: 14px; line-height: 1.7; }

/* results */
.result-card { text-align: center; width: min(470px, 100%); }
.result-score { display: flex; align-items: center; justify-content: center; gap: 18px; margin: 14px 0 9px; }
.result-score > div { width: 105px; display: flex; flex-direction: column; align-items: center; }
.result-badge { width: 38px; height: 44px; display: grid; place-items: center; clip-path: polygon(50% 0, 96% 22%, 88% 74%, 50% 100%, 12% 74%, 4% 22%); background: var(--home); color: #061116; font: 700 21px/1 'Rajdhani', sans-serif; margin-bottom: 5px; }
.result-score > div:last-child .result-badge { background: var(--away); }
.result-score b { font: 700 60px/.9 'Rajdhani', sans-serif; color: #fff; }
.result-score small { font-size: 11px; color: #93a8a6; margin-top: 7px; }
.result-score em { font: 300 34px/1 'Rajdhani', sans-serif; color: #577176; font-style: normal; }
.result-card h2 { font-size: 32px; margin: 10px 0 4px; }
.result-card p { margin: 0 0 20px; }
.result-card .modal-row { margin-top: 8px; }

/* toast */
.toast { position: absolute; z-index: 80; left: 50%; bottom: calc(94px + var(--safe-bottom)); transform: translate(-50%, 12px); display: flex; align-items: center; gap: 8px; padding: 9px 15px; background: rgba(4,18,23,.92); border: 1px solid rgba(217,255,67,.28); color: #d6e5df; font-size: 10px; opacity: 0; visibility: hidden; transition: .25s; pointer-events: none; max-width: 90vw; }
.toast.active { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.toast i { width: 5px; height: 5px; background: var(--lime); border-radius: 50%; }
.rotate-hint { display: none; }

/* ============ RESPONSIVE ============ */
@media (max-width: 980px) {
  .menu { padding: calc(16px + var(--safe-top)) calc(18px + var(--safe-right)) calc(13px + var(--safe-bottom)) calc(18px + var(--safe-left)); }
  .menu-hero { gap: 18px; }
  .hero-title-wrap { max-width: 49%; }
  .game-panel { width: min(360px, 47vw); padding: 14px; }
  .hero-sub { font-size: 11px; }
  .hero-stats > div { padding: 0 12px; }
  .title-fill { font-size: clamp(60px, 10vw, 94px); }
  .title-outline { font-size: clamp(28px, 5.6vw, 58px); }
  .meta-tags span { display: none; }
}

@media (max-width: 760px) {
  .menu { padding: calc(12px + var(--safe-top)) calc(14px + var(--safe-right)) calc(10px + var(--safe-bottom)) calc(14px + var(--safe-left)); background: linear-gradient(0deg, rgba(2,9,12,.8), rgba(2,9,12,.15) 55%, rgba(2,9,12,.55)); }
  .brand-crest { width: 31px; height: 36px; font-size: 22px; }
  .brand-lockup strong { font-size: 17px; }
  .brand-lockup small { font-size: 6px; }
  .season-chip { font-size: 7px; padding: 7px 8px; }
  .season-chip span, .season-chip i { display: none; }
  .menu-hero { flex-direction: column; justify-content: flex-end; align-items: stretch; padding: 0; gap: 10px; }
  .hero-title-wrap { max-width: 100%; text-align: center; padding: 3px 0 0; }
  .eyebrow { justify-content: center; font-size: 10px; margin-bottom: 2px; }
  .hero-title { align-items: center; }
  .title-fill { font-size: clamp(52px, 15vw, 84px); line-height: .8; }
  .title-outline { font-size: clamp(25px, 7.4vw, 40px); margin-top: 4px; }
  .hero-sub, .hero-stats { display: none; }
  .game-panel { width: 100%; padding: 10px; }
  .panel-top { padding-bottom: 7px; }
  .team-select { padding: 8px 0 8px; }
  .selected-team { margin-top: 6px; padding: 6px 9px; }
  .team-crest-large { width: 45px; height: 52px; }
  .team-crest-large span { font-size: 22px; }
  .selected-meta h2 { font-size: 20px; margin: 2px 0 3px; }
  .team-overall b { font-size: 24px; }
  .team-tags { display: none; }
  .team-strip { display: none; }
  .mode-grid { flex-direction: row; }
  .mode-btn { min-height: 48px; padding: 7px; gap: 7px; }
  .mode-icon { width: 31px; height: 31px; }
  .mode-icon svg { width: 18px; height: 18px; }
  .mode-copy b { font-size: 12px; }
  .mode-copy small { font-size: 7px; }
  .mode-key { display: none; }
  .mode-badge { font-size: 7px; padding: 3px; }
  .panel-footer { margin-top: 8px; padding-top: 7px; }
  .panel-footer .panel-note { display: none; }
  .menu-footer { display: none; }
  .topbar { padding: calc(9px + var(--safe-top)) calc(10px + var(--safe-right)) 0 calc(10px + var(--safe-left)); }
  .mini-logo { width: 30px; height: 34px; font-size: 19px; }
  .live-pill { height: 22px; padding: 0 7px; font-size: 8px; }
  .scorebug { min-width: 225px; height: 47px; }
  .score-team { min-width: 51px; padding: 0 7px; gap: 5px; }
  .score-badge { width: 20px; height: 24px; font-size: 11px; }
  .score-code { font-size: 11px; }
  .score-center { width: 86px; }
  .score-numbers b { font-size: 22px; }
  .score-clock { font-size: 8px; gap: 4px; }
  .score-clock em { padding-left: 4px; }
  .icon-btn { width: 30px; height: 30px; }
  .icon-btn svg { width: 15px; height: 15px; }
  .topbar-left .live-pill { display: none; }
  .hud-bottom { bottom: calc(9px + var(--safe-bottom)); left: calc(10px + var(--safe-left)); right: calc(10px + var(--safe-right)); }
  .desktop-hints, .charge-wrap { display: none; }
  .player-card { height: 43px; padding: 0 8px 0 5px; gap: 6px; background: rgba(3,15,20,.55); }
  .player-num { width: 28px; height: 30px; font-size: 17px; }
  .player-info { min-width: 76px; }
  .player-info small { font-size: 6px; }
  .player-info b { font-size: 10px; }
  .event-feed { top: calc(70px + var(--safe-top)); right: calc(10px + var(--safe-right)); }
  .feed-item { min-width: 150px; font-size: 8px; padding: 5px 8px; }
  .feed-item b { font-size: 8px; }
  .modal-card { padding: 20px 18px 17px; }
  .modal-card h2 { font-size: 23px; }
  .goal-content h2 { font-size: clamp(68px, 22vw, 120px); }
