export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.crowdGain = null;
    this.crowdFilter = null;
    this.enabled = true;
    this.excitement = 0.25;
    this.started = false;
  }

  unlock() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? 0.72 : 0;
      this.master.connect(this.ctx.destination);
      this.buildCrowd();
      this.buildDrone();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
    this.started = true;
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.setTargetAtTime(on ? 0.72 : 0, this.ctx.currentTime, 0.05);
  }

  buildCrowd() {
    const ctx = this.ctx;
    const len = ctx.sampleRate * 3;
    const buffer = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let c = 0; c < 2; c += 1) {
      const data = buffer.getChannelData(c);
      let last = 0;
      for (let i = 0; i < len; i += 1) {
        const white = Math.random() * 2 - 1;
        last = last * 0.97 + white * 0.03;
        data[i] = last * 2.3 + white * 0.025;
      }
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 520;
    filter.Q.value = 0.45;
    const gain = ctx.createGain();
    gain.gain.value = 0.1;
    source.connect(filter).connect(gain).connect(this.master);
    source.start();
    this.crowdGain = gain;
    this.crowdFilter = filter;
  }

  buildDrone() {
    const ctx = this.ctx;
    const master = ctx.createGain();
    master.gain.value = 0.022;
    master.connect(this.master);
    [55, 82.5, 110].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = i === 2 ? 'triangle' : 'sine';
      osc.frequency.value = freq;
      gain.gain.value = i === 2 ? 0.16 : 0.3;
      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.value = 0.06 + i * 0.025;
      lfoGain.gain.value = 0.08;
      lfo.connect(lfoGain).connect(gain.gain);
      osc.connect(gain).connect(master);
      osc.start();
      lfo.start();
    });
  }

  setExcitement(value) {
    this.excitement = value;
    if (!this.ctx) return;
    this.crowdGain.gain.setTargetAtTime(0.055 + value * 0.17, this.ctx.currentTime, 0.5);
    this.crowdFilter.frequency.setTargetAtTime(400 + value * 650, this.ctx.currentTime, 0.7);
  }

  tone(freq, duration, { type = 'sine', volume = 0.1, slide = 0, delay = 0 } = {}) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + duration);
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(volume, t + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.02);
  }

  noise(duration, volume = 0.08, freq = 900, q = 0.8, delay = 0, type = 'bandpass') {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const len = Math.floor(ctx.sampleRate * duration);
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i += 1) {
      const fade = Math.sin((i / len) * Math.PI);
      data[i] = (Math.random() * 2 - 1) * fade;
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(volume, t + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t);
  }

  kick(power = 0.7) {
    this.tone(105, 0.12, { type: 'sine', volume: 0.14 + power * 0.1, slide: -60 });
    this.noise(0.08, 0.08 + power * 0.05, 1600, 1.1);
  }

  pass() {
    this.tone(145, 0.07, { type: 'triangle', volume: 0.08, slide: -45 });
    this.noise(0.045, 0.035, 1100, 1.3);
  }

  tackle() {
    this.noise(0.18, 0.11, 320, 0.8, 0, 'lowpass');
    this.tone(72, 0.16, { type: 'sine', volume: 0.08, slide: -25 });
  }

  post() {
    this.tone(720, 0.32, { type: 'triangle', volume: 0.12, slide: -80 });
    this.tone(1150, 0.18, { type: 'sine', volume: 0.05, slide: -140 });
  }

  save() {
    this.noise(0.15, 0.08, 500, 0.9);
    this.tone(220, 0.09, { type: 'square', volume: 0.035, slide: 60 });
  }

  whistle(long = false) {
    this.tone(2250, long ? 0.5 : 0.18, { type: 'square', volume: 0.035 });
    this.tone(2650, long ? 0.5 : 0.18, { type: 'sine', volume: 0.025 });
    if (long) {
      this.tone(2250, 0.16, { type: 'square', volume: 0.03, delay: 0.28 });
      this.tone(2250, 0.34, { type: 'square', volume: 0.03, delay: 0.52 });
    }
  }

  goal() {
    this.noise(2.8, 0.21, 700, 0.25, 0, 'lowpass');
    this.noise(1.6, 0.1, 2200, 0.6, 0.08);
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.5, { type: 'triangle', volume: 0.05, delay: i * 0.07 }));
    this.tone(90, 0.6, { type: 'sine', volume: 0.13, slide: -25 });
  }

  click() {
    this.tone(660, 0.04, { type: 'sine', volume: 0.025 });
  }

  countdown(final = false) {
    this.tone(final ? 880 : 440, final ? 0.24 : 0.08, { type: 'triangle', volume: 0.05 });
  }

  fulltime() {
    this.whistle(true);
    this.noise(2.4, 0.13, 850, 0.3, 0.2, 'lowpass');
    [392, 523, 659].forEach((f, i) => this.tone(f, 0.6, { type: 'triangle', volume: 0.04, delay: 0.3 + i * 0.12 }));
  }

  halftime() {
    this.whistle(true);
    this.noise(1.4, 0.07, 900, 0.4);
  }
}

export class InputController {
  constructor() {
    this.keys = new Set();
    this.touch = {
      mx: 0,
      mz: 0,
      sprint: false,
      shootHeld: false,
      pass: false,
      tackle: false,
      switch: false,
      shootDown: false,
      shootUp: false,
    };
    this.edges = {
      shootDown: false,
      shootUp: false,
      pass: false,
      tackle: false,
      switch: false,
    };
    this.stickPointer = null;
    this.stickOrigin = { x: 0, y: 0 };
    this.stickRadius = 56;
    this.shootPointer = null;
    this.enabled = true;
    this.joystick = document.getElementById('joystick-zone');
    this.knob = document.getElementById('joystick-knob');
    this.bindKeyboard();
    this.bindTouch();
  }

  bindKeyboard() {
    const arrows = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'Tab']);
    window.addEventListener('keydown', (e) => {
      if (arrows.has(e.code)) e.preventDefault();
      if (e.code === 'Tab' && !e.repeat) {
        this.edges.switch = true;
        return;
      }
      if (e.code === 'Space') {
        if (!e.repeat) {
          this.edges.shootDown = true;
          this.touch.shootHeld = true;
        }
        return;
      }
      if ((e.code === 'KeyE' || e.code === 'KeyJ') && !e.repeat) this.edges.pass = true;
      if ((e.code === 'KeyF' || e.code === 'KeyK') && !e.repeat) this.edges.tackle = true;
      if (e.code === 'KeyQ' && !e.repeat) this.edges.switch = true;
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e) => {
      if (e.code === 'Space') {
        this.touch.shootHeld = false;
        this.edges.shootUp = true;
        return;
      }
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touch.shootHeld = false;
      this.touch.sprint = false;
      this.resetStick();
    });
  }

  bindTouch() {
    if (!this.joystick) return;
    const start = (e) => {
      if (this.stickPointer !== null) return;
      this.stickPointer = e.pointerId;
      const rect = this.joystick.getBoundingClientRect();
      this.stickOrigin = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
      this.stickRadius = rect.width * 0.36;
      this.joystick.setPointerCapture(e.pointerId);
      this.moveStick(e.clientX, e.clientY);
      e.preventDefault();
    };
    const move = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      this.moveStick(e.clientX, e.clientY);
      e.preventDefault();
    };
    const end = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      this.stickPointer = null;
      this.resetStick();
      e.preventDefault();
    };
    this.joystick.addEventListener('pointerdown', start);
    this.joystick.addEventListener('pointermove', move);
    this.joystick.addEventListener('pointerup', end);
    this.joystick.addEventListener('pointercancel', end);

    document.querySelectorAll('.touch-btn').forEach((btn) => {
      const action = btn.dataset.action;
      const down = (e) => {
        e.preventDefault();
        e.stopPropagation();
        btn.setPointerCapture(e.pointerId);
        btn.classList.add('held');
        if (action === 'shoot') {
          this.touch.shootHeld = true;
          this.touch.shootDown = true;
          this.edges.shootDown = true;
          this.shootPointer = e.pointerId;
        } else if (action === 'sprint') {
          this.touch.sprint = true;
        } else {
          this.touch[action] = true;
          this.edges[action] = true;
        }
      };
      const up = (e) => {
        e.preventDefault();
        btn.classList.remove('held');
        if (action === 'shoot') {
          if (this.shootPointer === e.pointerId || e.type === 'pointercancel') {
            this.touch.shootHeld = false;
            this.touch.shootUp = true;
            this.edges.shootUp = true;
            this.shootPointer = null;
          }
        } else if (action === 'sprint') {
          this.touch.sprint = false;
        }
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('lostpointercapture', up);
    });
  }

  moveStick(clientX, clientY) {
    let dx = clientX - this.stickOrigin.x;
    let dy = clientY - this.stickOrigin.y;
    const length = Math.hypot(dx, dy);
    if (length > this.stickRadius) {
      dx = (dx / length) * this.stickRadius;
      dy = (dy / length) * this.stickRadius;
    }
    this.touch.mx = dx / this.stickRadius;
    this.touch.mz = dy / this.stickRadius;
    if (this.knob) this.knob.style.transform = `translate(${dx * 0.7}px, ${dy * 0.7}px)`;
  }

  resetStick() {
    this.touch.mx = 0;
    this.touch.mz = 0;
    if (this.knob) this.knob.style.transform = 'translate(0, 0)';
  }

  reset() {
    this.edges = { shootDown: false, shootUp: false, pass: false, tackle: false, switch: false };
    this.touch.shootDown = false;
    this.touch.shootUp = false;
    this.touch.pass = false;
    this.touch.tackle = false;
    this.touch.switch = false;
    this.keys.clear();
    this.touch.shootHeld = false;
    this.touch.sprint = false;
    this.resetStick();
    document.querySelectorAll('.touch-btn').forEach((b) => b.classList.remove('held'));
  }

  read() {
    const k = this.keys;
    let mx = 0;
    let mz = 0;
    if (k.has('KeyA') || k.has('ArrowLeft')) mx -= 1;
    if (k.has('KeyD') || k.has('ArrowRight')) mx += 1;
    if (k.has('KeyW') || k.has('ArrowUp')) mz -= 1;
    if (k.has('KeyS') || k.has('ArrowDown')) mz += 1;
    mx += this.touch.mx;
    mz += this.touch.mz;
    const m = Math.hypot(mx, mz);
    if (m > 1) {
      mx /= m;
      mz /= m;
    }
    const input = {
      mx,
      mz,
      sprint: k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.sprint,
      shootHeld: this.touch.shootHeld,
      shootDown: this.edges.shootDown,
      shootUp: this.edges.shootUp,
      pass: this.edges.pass,
      tackle: this.edges.tackle,
      switch: this.edges.switch,
    };
    this.edges.shootDown = false;
    this.edges.shootUp = false;
    this.edges.pass = false;
    this.edges.tackle = false;
    this.edges.switch = false;
    return input;
  }

  isDown() {
    return {
      mx: (this.keys.has('KeyD') || this.keys.has('ArrowRight') ? 1 : 0) - (this.keys.has('KeyA') || this.keys.has('ArrowLeft') ? 1 : 0) + this.touch.mx,
      mz: (this.keys.has('KeyS') || this.keys.has('ArrowDown') ? 1 : 0) - (this.keys.has('KeyW') || this.keys.has('ArrowUp') ? 1 : 0) + this.touch.mz,
      shootHeld: this.touch.shootHeld,
      sprint: this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.touch.sprint,
    };
  }
}

import * as THREE from 'three';
import { COURT, ACTION, PHASE, clamp, lerp, angleLerp } from './constants.js';

const TAU = Math.PI * 2;

function canvas2d(w, h) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return [c, c.getContext('2d')];
}

function canvasTexture(canvas, aniso = 4) {
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = aniso;
  return texture;
}

function makePitchTexture() {
  const W = 2048;
  const H = 1120;
  const [canvas, ctx] = canvas2d(W, H);
  const px = (x) => ((x + 22) / 44) * W;
  const py = (z) => ((z + 12) / 24) * H;
  const fieldPx = (x) => (x / 44) * W;
  const fieldPy = (z) => (z / 24) * H;

  const grad = ctx.createLinearGradient(0, 0, W, H);
  grad.addColorStop(0, '#0e4d48');
  grad.addColorStop(0.46, '#116257');
  grad.addColorStop(1, '#0a3838');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // mowing bands
  for (let i = 0; i < 10; i += 1) {
    ctx.fillStyle = i % 2 ? 'rgba(175,255,213,.025)' : 'rgba(0,24,22,.055)';
    ctx.fillRect((i / 10) * W, 0, W / 10, H);
  }

  // soft scuffs and reflections
  for (let i = 0; i < 1400; i += 1) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    ctx.fillStyle = `rgba(${Math.random() > 0.5 ? '190,255,232' : '2,26,27'},${Math.random() * 0.035})`;
    ctx.fillRect(x, y, Math.random() * 5 + 1, Math.random() * 2 + 0.5);
  }
  const glow = ctx.createRadialGradient(W * 0.5, H * 0.42, 10, W * 0.5, H * 0.48, W * 0.5);
  glow.addColorStop(0, 'rgba(170,255,218,.075)');
  glow.addColorStop(1, 'rgba(0,30,30,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H);

  const line = 'rgba(225,255,205,.78)';
  ctx.strokeStyle = line;
  ctx.fillStyle = line;
  ctx.lineWidth = 5;

  // outer boundary
  ctx.strokeRect(px(-COURT.halfL), py(-COURT.halfW), fieldPx(COURT.halfL * 2), fieldPy(COURT.halfW * 2));
  // halfway
  ctx.beginPath();
  ctx.moveTo(px(0), py(-COURT.halfW));
  ctx.lineTo(px(0), py(COURT.halfW));
  ctx.stroke();
  // center circle + spot
  ctx.beginPath();
  ctx.arc(px(0), py(0), fieldPx(3), 0, TAU);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(px(0), py(0), 6, 0, TAU);
  ctx.fill();

  // futsal penalty arcs
  for (const side of [-1, 1]) {
    const goalX = side * COURT.halfL;
    const postZ = COURT.goalHalf;
    ctx.beginPath();
    ctx.arc(px(goalX), py(-postZ), fieldPx(6), 0, TAU);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(px(goalX), py(postZ), fieldPx(6), 0, TAU);
    ctx.stroke();
    const penX = side * (COURT.halfL - 6);
    ctx.beginPath();
    ctx.arc(px(penX), py(0), 5, 0, TAU);
    ctx.fill();
    // second penalty mark
    ctx.beginPath();
    ctx.arc(px(side * (COURT.halfL - 10)), py(0), 4, 0, TAU);
    ctx.fill();
  }

  // center watermark
  ctx.save();
  ctx.translate(px(0), py(0));
  ctx.rotate(-Math.PI / 2);
  ctx.font = '700 215px Rajdhani, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'rgba(218,255,195,.035)';
  ctx.fillText('KHAMASI', 0, 0);
  ctx.restore();

  // subtle center logo
  ctx.save();
  ctx.translate(px(0), py(0));
  ctx.globalAlpha = 0.085;
  ctx.strokeStyle = '#d9ff43';
  ctx.lineWidth = 10;
  ctx.beginPath();
  for (let i = 0; i < 6; i += 1) {
    const a = (i / 6) * TAU - Math.PI / 2;
    const x = Math.cos(a) * 42;
    const y = Math.sin(a) * 42;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.stroke();
  ctx.restore();

  return canvasTexture(canvas, 8);
}

function makeAdTexture(title, sub, bg, fg, accent) {
  const [canvas, ctx] = canvas2d(1024, 192);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, 1024, 192);
  const g = ctx.createLinearGradient(0, 0, 1024, 192);
  g.addColorStop(0, 'rgba(255,255,255,.08)');
  g.addColorStop(0.5, 'rgba(255,255,255,0)');
  g.addColorStop(1, 'rgba(0,0,0,.22)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1024, 192);
  ctx.save();
  ctx.translate(58, 40);
  ctx.fillStyle = accent;
  ctx.beginPath();
  for (let i = 0; i < 6; i += 1) {
    const a = (i / 6) * TAU - Math.PI / 2;
    const x = Math.cos(a) * 29;
    const y = Math.sin(a) * 29;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = bg;
  ctx.font = '700 24px Rajdhani, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('K', 0, 2);
  ctx.restore();
  ctx.fillStyle = fg;
  ctx.font = '700 64px Rajdhani, sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.letterSpacing = '6px';
  ctx.fillText(title, 112, 82);
  ctx.fillStyle = accent;
  ctx.font = '600 24px Rajdhani, sans-serif';
  ctx.letterSpacing = '8px';
  ctx.fillText(sub, 114, 137);
  ctx.strokeStyle = 'rgba(255,255,255,.16)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(940, 38);
  ctx.lineTo(940, 154);
  ctx.stroke();
  ctx.fillStyle = accent;
  ctx.font = '600 20px Rajdhani, sans-serif';
  ctx.save();
  ctx.translate(966, 96);
  ctx.rotate(Math.PI / 2);
  ctx.fillText('NIGHT LEAGUE', 0, 0);
  ctx.restore();
  return canvasTexture(canvas, 4);
}

function makeNetTexture() {
  const [canvas, ctx] = canvas2d(256, 256);
  ctx.clearRect(0, 0, 256, 256);
  ctx.strokeStyle = 'rgba(225,250,240,.62)';
  ctx.lineWidth = 2;
  for (let i = 0; i <= 256; i += 16) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i, 256);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(256, i);
    ctx.stroke();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(3, 2);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function makeBallTexture() {
  const [canvas, ctx] = canvas2d(512, 256);
  ctx.fillStyle = '#eef0e7';
  ctx.fillRect(0, 0, 512, 256);
  const spots = [
    [52, 60, 30], [150, 38, 26], [260, 62, 32], [380, 36, 26], [478, 66, 30],
    [100, 150, 32], [210, 142, 28], [330, 155, 33], [445, 144, 27],
    [50, 226, 29], [165, 218, 25], [285, 230, 31], [405, 215, 26],
  ];
  ctx.fillStyle = '#111b1e';
  for (const [x, y, r] of spots) {
    ctx.beginPath();
    for (let i = 0; i < 5; i += 1) {
      const a = (i / 5) * TAU - Math.PI / 2;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(20,40,44,.32)';
  ctx.lineWidth = 2;
  for (let x = 25; x < 512; x += 48) {
    ctx.beginPath();
    ctx.arc(x, 130, 40, 0.2, 2.5);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(217,255,67,.9)';
  ctx.font = '700 17px Rajdhani, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('KHAMASI', 256, 136);
  return canvasTexture(canvas, 8);
}

function makeNumberTexture(number, ink) {
  const [canvas, ctx] = canvas2d(128, 160);
  ctx.clearRect(0, 0, 128, 160);
  ctx.fillStyle = ink;
  ctx.font = '700 82px Rajdhani, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(number), 64, 83);
  return canvasTexture(canvas, 4);
}

function makeBannerTexture(teamA, teamB) {
  const [canvas, ctx] = canvas2d(1024, 256);
  ctx.fillStyle = '#051319';
  ctx.fillRect(0, 0, 1024, 256);
  const g = ctx.createLinearGradient(0, 0, 1024, 0);
  g.addColorStop(0, 'rgba(217,255,67,.12)');
  g.addColorStop(0.5, 'rgba(217,255,67,0)');
  g.addColorStop(1, 'rgba(71,242,208,.1)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1024, 256);
  ctx.fillStyle = '#d9ff43';
  ctx.font = '700 58px Rajdhani, sans-serif';
  ctx.textAlign = 'center';
  ctx.letterSpacing = '14px';
  ctx.fillText('KHAMASI', 512, 105);
  ctx.fillStyle = '#dcebe4';
  ctx.font = '600 30px Cairo, sans-serif';
  ctx.letterSpacing = '4px';
  ctx.fillText(`${teamA.name}  ×  ${teamB.name}`, 512, 168);
  ctx.fillStyle = 'rgba(255,255,255,.36)';
  ctx.font = '500 18px Rajdhani, sans-serif';
  ctx.letterSpacing = '10px';
  ctx.fillText('FIVE-A-SIDE  •  NIGHT LEAGUE', 512, 216);
  return canvasTexture(canvas, 4);
}

export class Arena {
  constructor(canvas, quality = 'high') {
    this.canvas = canvas;
    this.quality = quality;
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x031018);
    this.scene.fog = new THREE.FogExp2(0x031018, 0.012);
    this.camera = new THREE.PerspectiveCamera(43, 1, 0.1, 150);
    this.camera.position.set(10, 11, 23);
    this.cameraTarget = new THREE.Vector3(0, 0.4, 0);
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: quality === 'high',
      powerPreference: 'high-performance',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, quality === 'high' ? 1.7 : 1.1));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;
    this.renderer.shadowMap.enabled = quality === 'high';
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.mode = 'menu';
    this.time = 0;
    this.shake = 0;
    this.ballTrailPositions = [];
    this.playerViews = new Map();
    this.playerGroup = new THREE.Group();
    this.scene.add(this.playerGroup);
    this.menuPhase = 0;
    this.homeTeam = null;
    this.awayTeam = null;
    this.banner = null;
    this.confetti = null;
    this.confettiData = null;
    this.lastState = null;
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(canvas);
    this.resize();
    this.build();
  }

  resize() {
    const w = this.canvas.clientWidth || window.innerWidth;
    const h = this.canvas.clientHeight || window.innerHeight;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  build() {
    this.buildEnvironment();
    this.buildPitch();
    this.buildBoards();
    this.buildGoals();
    this.buildStands();
    this.buildLights();
    this.buildBall();
    this.buildConfetti();
  }

  buildEnvironment() {
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(80, 55),
      new THREE.MeshStandardMaterial({ color: 0x041319, roughness: 0.95, metalness: 0.05 }),
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.13;
    floor.receiveShadow = true;
    this.scene.add(floor);

    // dark court apron
    const apron = new THREE.Mesh(
      new THREE.PlaneGeometry(47, 27),
      new THREE.MeshStandardMaterial({ color: 0x061b20, roughness: 0.83, metalness: 0.15 }),
    );
    apron.rotation.x = -Math.PI / 2;
    apron.position.y = -0.02;
    apron.receiveShadow = true;
    this.scene.add(apron);

    // side rails behind boards
    const railMat = new THREE.MeshStandardMaterial({ color: 0x0b262d, metalness: 0.5, roughness: 0.5 });
    for (const z of [-11.15, 11.15]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(43, 0.08, 0.08), railMat);
      rail.position.set(0, 0.92, z);
      this.scene.add(rail);
      for (let x = -20; x <= 20; x += 4) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.06, 1.1, 0.06), railMat);
        post.position.set(x, 0.48, z);
        this.scene.add(post);
      }
    }

    // distant hall walls / darkness
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x04141b, roughness: 0.88 });
    const backWall = new THREE.Mesh(new THREE.BoxGeometry(64, 15, 0.5), wallMat);
    backWall.position.set(0, 5.5, -20.5);
    this.scene.add(backWall);
  }

  buildPitch() {
    const texture = makePitchTexture();
    texture.anisotropy = this.renderer.capabilities.getMaxAnisotropy();
    const geometry = new THREE.PlaneGeometry(44, 24);
    const material = new THREE.MeshStandardMaterial({
      map: texture,
      roughness: 0.58,
      metalness: 0.08,
      envMapIntensity: 0.2,
    });
    const pitch = new THREE.Mesh(geometry, material);
    pitch.rotation.x = -Math.PI / 2;
    pitch.position.y = 0.005;
    pitch.receiveShadow = true;
    this.scene.add(pitch);
  }

  buildBoards() {
    const ads = [
      makeAdTexture('KHAMASI', 'FIVE-A-SIDE', '#081f25', '#e9f7df', '#d9ff43'),
      makeAdTexture('VELOCITY', 'SPORT ENERGY', '#13221d', '#eaf6e3', '#47f2d0'),
      makeAdTexture('NIGHT LEAGUE', 'SEASON 01', '#1e1112', '#fff0e8', '#ff705d'),
      makeAdTexture('ARENA 5', 'PLAY BOLD', '#111527', '#f4efff', '#b18cff'),
    ];
    const boardMat = new THREE.MeshStandardMaterial({ color: 0x07191e, roughness: 0.45, metalness: 0.55 });
    const glowMat = new THREE.MeshBasicMaterial({ color: 0xd9ff43, transparent: true, opacity: 0.52 });
    const adMats = ads.map((map) => new THREE.MeshStandardMaterial({
      map,
      emissive: 0xffffff,
      emissiveMap: map,
      emissiveIntensity: 0.45,
      roughness: 0.45,
      side: THREE.DoubleSide,
    }));
    const adGeo = new THREE.PlaneGeometry(4.4, 0.82);
    const zPositions = [10.5, -10.5];
    zPositions.forEach((z, side) => {
      for (let i = 0; i < 10; i += 1) {
        const x = -19.8 + i * 4.4;
        const mesh = new THREE.Mesh(adGeo, adMats[(i + side) % 4]);
        mesh.position.set(x, 0.46, z + (z > 0 ? 0.03 : -0.03));
        mesh.rotation.y = side === 0 ? Math.PI : 0;
        this.scene.add(mesh);
        if (i % 2 === 0) {
          const gl = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.025, 0.03), glowMat);
          gl.position.set(x, 0.065, z + (z > 0 ? 0.06 : -0.06));
          this.scene.add(gl);
        }
      }
      const base = new THREE.Mesh(new THREE.BoxGeometry(44.2, 0.88, 0.13), boardMat);
      base.position.set(0, 0.45, z);
      this.scene.add(base);
    });
    // end boards
    const endAdGeo = new THREE.PlaneGeometry(3.7, 0.82);
    for (const side of [-1, 1]) {
      for (let i = 0; i < 4; i += 1) {
        const z = -8.25 + i * 4.4;
        if (Math.abs(z) < 2.4) continue;
        const ad = new THREE.Mesh(endAdGeo, adMats[(i + (side > 0 ? 1 : 3)) % 4]);
        ad.position.set(side * 20.54, 0.46, z);
        ad.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
        this.scene.add(ad);
      }
      const base = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.88, 21), boardMat);
      base.position.set(side * 20.55, 0.45, 0);
      this.scene.add(base);
    }
  }

  buildGoals() {
    const netTex = makeNetTexture();
    const netMat = new THREE.MeshStandardMaterial({
      map: netTex,
      transparent: true,
      alphaTest: 0.05,
      side: THREE.DoubleSide,
      roughness: 0.8,
      color: 0xcdebe5,
      opacity: 0.75,
    });
    const frameMat = new THREE.MeshStandardMaterial({ color: 0xeaf5ef, roughness: 0.32, metalness: 0.62 });
    const backFrameMat = new THREE.MeshStandardMaterial({ color: 0x40625f, roughness: 0.55, metalness: 0.4 });
    for (const side of [-1, 1]) {
      const group = new THREE.Group();
      const x = side * (COURT.halfL + 0.35);
      const goalW = COURT.goalHalf * 2;
      const h = COURT.goalHeight;
      const depth = COURT.netDepth;
      const postGeo = new THREE.CylinderGeometry(0.065, 0.065, h, 10);
      for (const z of [-COURT.goalHalf, COURT.goalHalf]) {
        const post = new THREE.Mesh(postGeo, frameMat);
        post.position.set(x, h / 2, z);
        post.castShadow = true;
        group.add(post);
      }
      const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.065, goalW + 0.13, 10), frameMat);
      bar.rotation.x = Math.PI / 2;
      bar.position.set(x, h, 0);
      bar.castShadow = true;
      group.add(bar);

      // net: back, two sides, roof
      const back = new THREE.Mesh(new THREE.PlaneGeometry(goalW, h), netMat);
      back.position.set(x + side * depth, h / 2, 0);
      back.rotation.y = side > 0 ? Math.PI / 2 : -Math.PI / 2;
      group.add(back);
      for (const z of [-COURT.goalHalf, COURT.goalHalf]) {
        const pane = new THREE.Mesh(new THREE.PlaneGeometry(depth, h), netMat);
        pane.position.set(x + side * depth / 2, h / 2, z);
        pane.rotation.y = 0;
        group.add(pane);
      }
      const roof = new THREE.Mesh(new THREE.PlaneGeometry(depth, goalW), netMat);
      roof.position.set(x + side * depth / 2, h, 0);
      roof.rotation.x = Math.PI / 2;
      group.add(roof);

      // back frame
      for (const z of [-COURT.goalHalf, COURT.goalHalf]) {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, h * 0.9, 6), backFrameMat);
        pole.position.set(x + side * depth, h * 0.45, z);
        group.add(pole);
      }
      const backBar = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, goalW, 6), backFrameMat);
      backBar.rotation.x = Math.PI / 2;
      backBar.position.set(x + side * depth, h * 0.9, 0);
      group.add(backBar);
      this.scene.add(group);
    }
  }

  buildStands() {
    const standMat = new THREE.MeshStandardMaterial({ color: 0x071b23, roughness: 0.82, metalness: 0.2 });
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x0e3038, roughness: 0.6, metalness: 0.38 });
    const crowdGeo = new THREE.BoxGeometry(0.18, 0.3, 0.18);
    const crowdMat = new THREE.MeshLambertMaterial({ color: 0xffffff });
    const colours = ['#d9ff43', '#47f2d0', '#ff705d', '#e9ece0', '#5f9ec7', '#c99b56', '#8b67d1'];
    const instances = [];
    const rows = 10;
    for (const side of [-1, 1]) {
      for (let r = 0; r < rows; r += 1) {
        const z = side * (12.1 + r * 0.56);
        const y = 0.42 + r * 0.31;
        const tier = new THREE.Mesh(new THREE.BoxGeometry(50, 0.34, 0.58), standMat);
        tier.position.set(0, y - 0.2, z);
        tier.receiveShadow = true;
        this.scene.add(tier);
        const trim = new THREE.Mesh(new THREE.BoxGeometry(50, 0.035, 0.05), trimMat);
        trim.position.set(0, y, z - side * 0.27);
        this.scene.add(trim);
        for (let i = 0; i < 76; i += 1) {
          const x = -24 + i * 0.64 + (r % 2) * 0.12;
          if (Math.random() < 0.13) continue;
          instances.push({ x, y: y + 0.17, z: z + (Math.random() - 0.5) * 0.1, color: colours[Math.floor(Math.random() * colours.length)], rot: side < 0 ? Math.PI : 0 });
        }
      }
    }
    // end stands
    for (const side of [-1, 1]) {
      for (let r = 0; r < 7; r += 1) {
        const x = side * (23.2 + r * 0.62);
        const y = 0.34 + r * 0.32;
        const tier = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.36, 35), standMat);
        tier.position.set(x, y - 0.2, 0);
        this.scene.add(tier);
        for (let i = 0; i < 42; i += 1) {
          const z = -10.5 + i * 0.51;
          if (Math.random() < 0.18) continue;
          instances.push({ x: x + (Math.random() - 0.5) * 0.1, y: y + 0.17, z, color: colours[Math.floor(Math.random() * colours.length)], rot: side > 0 ? -Math.PI / 2 : Math.PI / 2 });
        }
      }
    }
    const crowd = new THREE.InstancedMesh(crowdGeo, crowdMat, instances.length);
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    instances.forEach((item, i) => {
      dummy.position.set(item.x, item.y, item.z);
      dummy.rotation.y = item.rot;
      dummy.updateMatrix();
      crowd.setMatrixAt(i, dummy.matrix);
      color.set(item.color);
      crowd.setColorAt(i, color);
    });
    crowd.instanceMatrix.needsUpdate = true;
    crowd.instanceColor.needsUpdate = true;
    this.scene.add(crowd);

    // far side wall and roof structure
    const wall = new THREE.Mesh(new THREE.BoxGeometry(52, 8, 0.5), new THREE.MeshStandardMaterial({ color: 0x04141b, roughness: 0.85 }));
    wall.position.set(0, 4, -18.7);
    this.scene.add(wall);
    const roofBeamMat = new THREE.MeshStandardMaterial({ color: 0x0b2028, metalness: 0.7, roughness: 0.42 });
    for (let x = -22; x <= 22; x += 5.5) {
      const beam = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 16), roofBeamMat);
      beam.position.set(x, 11.7, -5.5);
      beam.rotation.x = -0.08;
      this.scene.add(beam);
    }
    for (let i = 0; i < 3; i += 1) {
      const beam = new THREE.Mesh(new THREE.BoxGeometry(55, 0.18, 0.18), roofBeamMat);
      beam.position.set(0, 11.8 + i * 0.25, -12.5 + i * 0.1);
      this.scene.add(beam);
    }

    // hanging jumbotron
    const screenFrame = new THREE.Mesh(new THREE.BoxGeometry(9.4, 2.7, 0.35), new THREE.MeshStandardMaterial({ color: 0x02090c, metalness: 0.6, roughness: 0.35 }));
    screenFrame.position.set(0, 8.35, -17.9);
    this.scene.add(screenFrame);
    this.screen = new THREE.Mesh(
      new THREE.PlaneGeometry(9, 2.3),
      new THREE.MeshBasicMaterial({ color: 0x05151c }),
    );
    this.screen.position.set(0, 8.35, -17.7);
    this.scene.add(this.screen);
    this.screenLight = new THREE.Mesh(
      new THREE.PlaneGeometry(9, 0.06),
      new THREE.MeshBasicMaterial({ color: 0xd9ff43 }),
    );
    this.screenLight.position.set(0, 7.18, -17.68);
    this.scene.add(this.screenLight);
    for (let x = -4; x <= 4; x += 2) {
      const hanger = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1.1, 5), roofBeamMat);
      hanger.position.set(x, 9.85, -17.9);
      this.scene.add(hanger);
    }
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0x8ee3df, 0x071512, 0.85);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xfff8df, 2.5);
    key.position.set(9, 28, 10);
    key.castShadow = this.quality === 'high';
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -28;
    key.shadow.camera.right = 28;
    key.shadow.camera.top = 24;
    key.shadow.camera.bottom = -24;
    key.shadow.camera.near = 2;
    key.shadow.camera.far = 65;
    key.shadow.bias = -0.0006;
    key.shadow.normalBias = 0.02;
    this.scene.add(key);
    this.scene.add(key.target);
    key.target.position.set(0, 0, 0);

    const fill = new THREE.DirectionalLight(0x76e7e0, 0.55);
    fill.position.set(-14, 12, -12);
    this.scene.add(fill);

    const lightMat = new THREE.MeshBasicMaterial({ color: 0xd9ff43 });
    const housing = new THREE.MeshStandardMaterial({ color: 0x051318, metalness: 0.6, roughness: 0.3 });
    const positions = [[-18, 12.5, 12.5], [18, 12.5, 12.5], [-18, 12.5, -12.5], [18, 12.5, -12.5]];
    positions.forEach(([x, y, z]) => {
      const box = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.7, 0.45), housing);
      box.position.set(x, y, z);
      box.lookAt(0, 0, 0);
      this.scene.add(box);
      for (let i = -1; i <= 1; i += 1) {
        const lamp = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.28, 0.06), lightMat);
        lamp.position.set(x + i * 0.68, y, z + (z > 0 ? -0.26 : 0.26));
        lamp.lookAt(0, 0, 0);
        this.scene.add(lamp);
      }
      const spot = new THREE.PointLight(0xd9ffb8, 34, 32, 1.8);
      spot.position.set(x * 0.75, 9, z * 0.55);
      this.scene.add(spot);
    });

    // light shafts
    const shaftMat = new THREE.MeshBasicMaterial({
      color: 0xcfffb0,
      transparent: true,
      opacity: 0.025,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    for (const [x, y, z] of positions) {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(4.3, 18, 20, 1, true), shaftMat);
      cone.position.set(x * 0.7, y - 8, z * 0.55);
      cone.rotation.z = x > 0 ? 0.15 : -0.15;
      this.scene.add(cone);
    }

    // dust motes in the beams
    const moteGeo = new THREE.BufferGeometry();
    const motePos = new Float32Array(420 * 3);
    for (let i = 0; i < 420; i += 1) {
      motePos[i * 3] = (Math.random() - 0.5) * 40;
      motePos[i * 3 + 1] = Math.random() * 10 + 2;
      motePos[i * 3 + 2] = (Math.random() - 0.5) * 20;
    }
    moteGeo.setAttribute('position', new THREE.BufferAttribute(motePos, 3));
    const motes = new THREE.Points(moteGeo, new THREE.PointsMaterial({ color: 0xcaffb0, size: 0.035, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending }));
    this.scene.add(motes);
  }

  buildBall() {
    const texture = makeBallTexture();
    const mat = new THREE.MeshStandardMaterial({ map: texture, roughness: 0.42, metalness: 0.04 });
    this.ball = new THREE.Mesh(new THREE.SphereGeometry(COURT.ballRadius, 20, 14), mat);
    this.ball.castShadow = true;
    this.ball.position.set(0, COURT.ballRadius, 0);
    this.scene.add(this.ball);

    const glow = new THREE.PointLight(0xf5ffce, 1.8, 4, 2);
    glow.position.set(0, 0.3, 0);
    this.ball.add(glow);

    const trailGeo = new THREE.BufferGeometry();
    const pos = new Float32Array(22 * 3);
    trailGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.trail = new THREE.Line(trailGeo, new THREE.LineBasicMaterial({ color: 0xd9ff43, transparent: true, opacity: 0 }));
    this.trail.frustumCulled = false;
    this.scene.add(this.trail);
  }

  buildConfetti() {
    const count = 260;
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({ size: 0.13, vertexColors: true, transparent: true, opacity: 0, depthWrite: false });
    this.confetti = new THREE.Points(geo, mat);
    this.confetti.frustumCulled = false;
    this.scene.add(this.confetti);
    this.confettiData = [];
  }

  setMenuTeams(home, away) {
    this.homeTeam = home;
    this.awayTeam = away;
    this.setScreenTeam(home, away);
    this.buildShowcase();
  }

  setScreenTeam(home, away) {
    if (this.screen) {
      const old = this.screen.material.map;
      this.screen.material.map = makeBannerTexture(home, away);
      this.screen.material.needsUpdate = true;
      old?.dispose();
    }
  }

  createPlayerView(player, team, isGk, isHome) {
    const root = new THREE.Group();
    const body = new THREE.Group();
    root.add(body);
    const ink = team.ink || '#071215';
    const shirtMat = new THREE.MeshStandardMaterial({ color: isGk ? team.kit.gk : team.kit.shirt, roughness: 0.72, metalness: 0.02 });
    const sleeveMat = new THREE.MeshStandardMaterial({ color: isGk ? team.kit.gk : team.kit.sleeve, roughness: 0.72 });
    const shortsMat = new THREE.MeshStandardMaterial({ color: isGk ? '#1b2730' : team.kit.shorts, roughness: 0.75 });
    const sockMat = new THREE.MeshStandardMaterial({ color: isGk ? team.kit.gk : team.kit.socks, roughness: 0.78 });
    const skinPalette = ['#8d583d', '#b87750', '#d09a72', '#6f452f', '#c88b60', '#e1b089'];
    const skinMat = new THREE.MeshStandardMaterial({ color: skinPalette[player.index % skinPalette.length], roughness: 0.82 });
    const hairMat = new THREE.MeshStandardMaterial({ color: player.index % 3 === 0 ? '#211814' : player.index % 3 === 1 ? '#0b0f11' : '#53362a', roughness: 0.94 });

    const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.2, 0.5, 7), shirtMat);
    torso.position.y = 1.15;
    torso.castShadow = true;
    body.add(torso);
    const shoulder = new THREE.Mesh(new THREE.CylinderGeometry(0.27, 0.23, 0.14, 7), sleeveMat);
    shoulder.position.y = 1.34;
    body.add(shoulder);
    const shorts = new THREE.Mesh(new THREE.CylinderGeometry(0.205, 0.24, 0.26, 7), shortsMat);
    shorts.position.y = 0.81;
    body.add(shorts);
    const shortsTrim = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.035, 0.02), new THREE.MeshBasicMaterial({ color: team.accent }));
    shortsTrim.position.set(0, 0.86, 0.205);
    body.add(shortsTrim);

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.155, 10, 7), skinMat);
    head.position.y = 1.55;
    head.castShadow = true;
    body.add(head);
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 5, 0, TAU, 0, Math.PI * 0.58), hairMat);
    hair.position.y = 1.582;
    hair.scale.set(1.045, 0.86, 1.045);
    body.add(hair);
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.08, 0.12, 6), skinMat);
    neck.position.y = 1.42;
    body.add(neck);

    const leftLeg = new THREE.Group();
    const rightLeg = new THREE.Group();
    leftLeg.position.set(-0.115, 0.74, 0);
    rightLeg.position.set(0.115, 0.74, 0);
    for (const [leg, x] of [[leftLeg, -1], [rightLeg, 1]]) {
      const thigh = new THREE.Mesh(new THREE.CapsuleGeometry(0.082, 0.4, 3, 6), sockMat);
      thigh.position.y = -0.25;
      thigh.castShadow = true;
      leg.add(thigh);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.145, 0.1, 0.27), new THREE.MeshStandardMaterial({ color: 0x0b1114, roughness: 0.5, metalness: 0.3 }));
      boot.position.set(0, -0.51, 0.07);
      boot.castShadow = true;
      leg.add(boot);
      body.add(leg);
    }

    const leftArm = new THREE.Group();
    const rightArm = new THREE.Group();
    leftArm.position.set(-0.285, 1.33, 0);
    rightArm.position.set(0.285, 1.33, 0);
    for (const [arm, side] of [[leftArm, -1], [rightArm, 1]]) {
      const limb = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.34, 3, 6), skinMat);
      limb.position.y = -0.19;
      limb.castShadow = true;
      arm.add(limb);
      const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.077, 0.09, 0.15, 6), sleeveMat);
      sleeve.position.y = -0.03;
      arm.add(sleeve);
      arm.rotation.z = side * -0.12;
      body.add(arm);
    }
    if (isGk) {
      for (const [arm, side] of [[leftArm, -1], [rightArm, 1]]) {
        const glove = new THREE.Mesh(new THREE.SphereGeometry(0.085, 6, 5), new THREE.MeshStandardMaterial({ color: 0xd9ff43, roughness: 0.65 }));
        glove.position.set(0, -0.4, 0.015);
        arm.add(glove);
      }
    }

    const number = new THREE.Mesh(
      new THREE.PlaneGeometry(0.27, 0.34),
      new THREE.MeshBasicMaterial({ map: makeNumberTexture(player.number, ink), transparent: true, depthWrite: false }),
    );
    number.position.set(0, 1.14, -0.208);
    number.rotation.y = Math.PI;
    body.add(number);

    const ringMat = new THREE.MeshBasicMaterial({ color: isHome ? 0xd9ff43 : 0x47f2d0, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.48, 0.61, 32), ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.028;
    root.add(ring);
    const arrowMat = new THREE.MeshBasicMaterial({ color: isHome ? 0xd9ff43 : 0x47f2d0, transparent: true, opacity: 0.95 });
    const arrow = new THREE.Mesh(new THREE.ConeGeometry(0.115, 0.24, 3), arrowMat);
    arrow.position.y = 2.14;
    arrow.rotation.z = Math.PI;
    root.add(arrow);

    this.playerGroup.add(root);
    const view = { root, body, leftLeg, rightLeg, leftArm, rightArm, ring, arrow, phase: Math.random() * TAU, speed: 0, player, team, isGk };
    this.playerViews.set(player.id, view);
    return view;
  }

  buildShowcase() {
    for (const view of this.playerViews.values()) {
      this.playerGroup.remove(view.root);
      view.root.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose?.();
      });
    }
    this.playerViews.clear();
    if (!this.homeTeam) return;
    const kick = [
      { role: 'GK', x: -17.5, z: 0 },
      { role: 'LB', x: -7, z: -4.8 },
      { role: 'RB', x: -7, z: 4.8 },
      { role: 'CM', x: 0.5, z: 0.5 },
      { role: 'ST', x: 6, z: -1.6 },
    ];
    const fake = [];
    for (let t = 0; t < 2; t += 1) {
      const team = t === 0 ? this.homeTeam : this.awayTeam;
      for (let i = 0; i < 5; i += 1) {
        finalPos(fake, t, i, kick, team);
      }
    }
    this.showcasePlayers = fake;
    for (const p of fake) {
      this.createPlayerView(p, p.team, p.role === 'GK', p.teamIndex === 0);
    }
    this.menuBallPos = new THREE.Vector3(0, COURT.ballRadius, 0);
  }

  setMatchPlayers(players, homeTeam, awayTeam) {
    this.homeTeam = homeTeam;
    this.awayTeam = awayTeam;
    for (const view of this.playerViews.values()) {
      this.playerGroup.remove(view.root);
    }
    this.playerViews.clear();
    for (const p of players) {
      const team = p.team === 0 ? homeTeam : awayTeam;
      this.createPlayerView(p, team, p.role === 'GK', p.team === 0);
    }
  }

  setMode(mode) {
    this.mode = mode;
    if (mode === 'menu') {
      this.buildShowcase();
    }
  }

  updateMenu(dt, now, selectedTeam) {
    this.menuPhase += dt;
    const t = now * 0.00009;
    const bob = Math.sin(now * 0.00045);
    const target = new THREE.Vector3(0, 0.6, 0);
    const cam = new THREE.Vector3(
      Math.sin(t * 1.7 + 0.6) * 14.5,
      8.3 + bob * 0.35,
      18.5 + Math.cos(t * 1.25) * 3.5,
    );
    this.camera.position.lerp(cam, 1 - Math.exp(-1.5 * dt));
    this.cameraTarget.lerp(target, 1 - Math.exp(-1.6 * dt));
    this.camera.lookAt(this.cameraTarget);
    if (this.showcasePlayers) {
      for (const p of this.showcasePlayers) {
        const view = this.playerViews.get(p.id);
        if (!view) continue;
        const idx = p.index;
        const sway = Math.sin(now * 0.0011 + idx * 1.7) * 0.12;
        view.root.position.x = p.x;
        view.root.position.z = p.z;
        view.root.rotation.y = Math.PI / 2 - p.dir;
        view.body.position.y = Math.sin(now * 0.0018 + idx) * 0.008;
        view.leftArm.rotation.x = sway;
        view.rightArm.rotation.x = -sway;
        view.leftLeg.rotation.x = -sway * 0.6;
        view.rightLeg.rotation.x = sway * 0.6;
      }
      const ball = this.ball;
      ball.position.y = COURT.ballRadius + Math.abs(Math.sin(now * 0.0022)) * 0.35;
      ball.position.x = Math.sin(now * 0.0007) * 0.2;
      ball.rotation.z += dt * 0.7;
    }
    this.updateConfetti(dt);
    if (this.confetti) this.confetti.material.opacity = Math.max(0, this.confetti.material.opacity - dt * 0.7);
  }

  updateGame(state, dt, now, ownTeam, cameraMode = 'game') {
    this.lastState = state;
    for (const p of state.players) {
      let view = this.playerViews.get(p.id);
      if (!view) {
        const team = p.team === 0 ? this.homeTeam : this.awayTeam;
        view = this.createPlayerView(p, team, p.role === 'GK', p.team === 0);
      }
      view.root.position.x = lerp(view.root.position.x, p.x, 1 - Math.exp(-26 * dt));
      view.root.position.z = lerp(view.root.position.z, p.z, 1 - Math.exp(-26 * dt));
      const wantedRot = Math.PI / 2 - p.dir;
      view.root.rotation.y = angleLerp(view.root.rotation.y, wantedRot, 1 - Math.exp(-16 * dt));
      const speed = Math.hypot(p.vx || 0, p.vz || 0);
      view.speed = lerp(view.speed, speed, 1 - Math.exp(-10 * dt));
      this.animatePlayer(view, p, dt, now, state.phase === PHASE.goal);
      const controlled = state.active && state.active[p.team] === p.id && p.team === ownTeam;
      view.ring.visible = controlled;
      view.arrow.visible = controlled;
      if (controlled) {
        const pulse = 1 + Math.sin(now * 0.004) * 0.08;
        view.ring.scale.setScalar(pulse);
        view.arrow.position.y = 2.14 + Math.sin(now * 0.004) * 0.05;
      }
    }
    const ball = this.ball;
    ball.position.set(state.ball.x, state.ball.y, state.ball.z);
    ball.rotation.x += (state.ball.vz || 0) * dt * 3.1;
    ball.rotation.z -= (state.ball.vx || 0) * dt * 3.1;
    this.updateTrail(state, dt);
    this.updateConfetti(dt);
    this.updateCamera(state, dt, now, cameraMode);
    // crowd excitement drives ambient through CSS? handled by audio
  }

  animatePlayer(view, p, dt, now, celebration) {
    const speed = view.speed || 0;
    const action = p.action || 0;
    const actionT = p.actionT || 0;
    const moving = speed > 0.35;
    const runSpeed = clamp(speed / 5.4, 0.25, 1.5);
    view.phase += dt * (moving ? 8 + runSpeed * 5 : 2.2);
    let swing = moving ? Math.sin(view.phase) * (0.48 + runSpeed * 0.2) : Math.sin(view.phase) * 0.025;
    let armSwing = moving ? -Math.sin(view.phase) * (0.38 + runSpeed * 0.18) : Math.sin(view.phase * 0.7) * 0.02;
    let bodyY = moving ? Math.abs(Math.sin(view.phase * 2)) * 0.022 : Math.sin(now * 0.002 + p.index) * 0.006;
    let lean = moving ? 0.08 + runSpeed * 0.055 : 0;
    let bodyRot = 0;
    let bodyZ = 0;
    view.body.position.y = bodyY;
    view.body.rotation.x = lean;
    view.body.rotation.z = 0;
    view.body.rotation.y = 0;
    view.root.position.y = 0;

    if (action === ACTION.kick || action === ACTION.shoot || action === ACTION.pass) {
      const kickPhase = Math.sin(clamp(1 - actionT / 0.28, 0, 1) * Math.PI);
      swing = kickPhase * 0.9;
      armSwing = -kickPhase * 0.7;
      bodyRot = kickPhase * 0.12;
    } else if (action === ACTION.slide) {
      const p2 = clamp(actionT / 0.55, 0, 1);
      view.root.position.y = 0.16 + p2 * 0.18;
      view.body.rotation.z = -1.02 + p2 * 0.15;
      view.body.rotation.x = -0.25;
      swing = 0.35;
      armSwing = 0.5;
    } else if (action === ACTION.dive) {
      const p2 = clamp(actionT / 0.55, 0, 1);
      view.root.position.y = 0.25;
      view.body.rotation.z = (p.goalSide || 1) * (-1.12 + p2 * 0.3);
      bodyZ = 0;
      swing = 0.4;
      armSwing = 0.85;
    } else if (action === ACTION.hurt) {
      view.body.rotation.z = 0.2;
      bodyY = 0.03;
    } else if (celebration || action === ACTION.celebrate) {
      const hop = Math.abs(Math.sin(now * 0.011 + p.index));
      view.root.position.y = hop * 0.28;
      view.body.rotation.x = -0.1;
      view.leftArm.rotation.x = Math.PI * 0.82;
      view.rightArm.rotation.x = Math.PI * 0.82;
      view.leftArm.rotation.z = -0.3;
      view.rightArm.rotation.z = 0.3;
      view.leftLeg.rotation.x = -0.2;
      view.rightLeg.rotation.x = 0.2;
      return;
    }
    view.leftLeg.rotation.x = swing;
    view.rightLeg.rotation.x = -swing;
    view.leftArm.rotation.x = armSwing;
    view.rightArm.rotation.x = -armSwing;
    view.leftArm.rotation.z = -0.12;
    view.rightArm.rotation.z = 0.12;
    view.body.rotation.y = bodyRot;
    view.body.rotation.z = bodyZ;
  }

  updateTrail(state, dt) {
    const speed = Math.hypot(state.ball.vx || 0, state.ball.vz || 0) + Math.abs(state.ball.vy || 0);
    this.ballTrailPositions.unshift(new THREE.Vector3(state.ball.x, state.ball.y, state.ball.z));
    if (this.ballTrailPositions.length > 22) this.ballTrailPositions.pop();
    const attr = this.trail.geometry.getAttribute('position');
    this.ballTrailPositions.forEach((v, i) => {
      attr.setXYZ(i, v.x, v.y, v.z);
    });
    for (let i = this.ballTrailPositions.length; i < 22; i += 1) {
      const last = this.ballTrailPositions[this.ballTrailPositions.length - 1] || new THREE.Vector3();
      attr.setXYZ(i, last.x, last.y, last.z);
    }
    attr.needsUpdate = true;
    this.trail.material.opacity = lerp(this.trail.material.opacity, clamp((speed - 9) / 20, 0, 0.5), 0.2);
  }

  updateCamera(state, dt, now, cameraMode) {
    let camX;
    let camY;
    let camZ;
    let lookX;
    let lookY;
    let lookZ;
    const ball = state.ball;
    if (state.phase === PHASE.goal) {
      const side = state.lastGoalTeam === 0 ? 1 : -1;
      camX = side * 13.6;
      camY = 7.9;
      camZ = ball.z * 0.3 + 9.5;
      lookX = side * 19.7;
      lookY = 0.8;
      lookZ = ball.z * 0.3;
      camY += Math.sin(now * 0.002) * 0.12;
    } else if (state.phase === PHASE.halftime || state.phase === PHASE.fulltime) {
      const t = now * 0.00008;
      camX = Math.sin(t) * 9;
      camY = 10.5;
      camZ = 20.5;
      lookX = 0;
      lookY = 0;
      lookZ = 0;
    } else {
      camX = clamp(ball.x * 0.5, -7.6, 7.6);
      camY = 13.8 + clamp(Math.abs(ball.x) - 12, 0, 7) * 0.17;
      camZ = 18.4;
      lookX = lerp(ball.x * 0.62, 0, 0.2);
      lookY = 0.6;
      lookZ = ball.z * 0.3;
    }
    if (cameraMode === 'wide') {
      camX = 0;
      camY = 15.2;
      camZ = 23.5;
      lookX = 0;
      lookY = 0.5;
      lookZ = 0;
    }
    const damping = 1 - Math.exp(-3.5 * dt);
    this.camera.position.x = lerp(this.camera.position.x, camX, damping);
    this.camera.position.y = lerp(this.camera.position.y, camY, damping);
    this.camera.position.z = lerp(this.camera.position.z, camZ, damping);
    this.cameraTarget.x = lerp(this.cameraTarget.x, lookX, damping);
    this.cameraTarget.y = lerp(this.cameraTarget.y, lookY, damping);
    this.cameraTarget.z = lerp(this.cameraTarget.z, lookZ, damping);
    if (this.shake > 0.001) {
      this.shake *= Math.exp(-4.5 * dt);
      this.camera.position.x += (Math.random() - 0.5) * this.shake;
      this.camera.position.y += (Math.random() - 0.5) * this.shake * 0.5;
    } else this.shake = 0;
    this.camera.lookAt(this.cameraTarget);
  }

  addShake(amount) {
    this.shake = Math.min(0.5, this.shake + amount);
  }

  celebrate(team) {
    const side = team === 0 ? 1 : -1;
    const origin = new THREE.Vector3(side * 18.5, 1.2, (Math.random() - 0.5) * 2);
    this.confettiData = [];
    const colors = [new THREE.Color(0xd9ff43), new THREE.Color(0x47f2d0), new THREE.Color(0xff705d), new THREE.Color(0xffffff)];
    const positions = this.confetti.geometry.getAttribute('position');
    const colorAttr = this.confetti.geometry.getAttribute('color');
    for (let i = 0; i < 260; i += 1) {
      positions.setXYZ(i, origin.x + (Math.random() - 0.5) * 2, origin.y + Math.random() * 2, origin.z + (Math.random() - 0.5) * 3);
      const c = colors[i % colors.length];
      colorAttr.setXYZ(i, c.r, c.g, c.b);
      this.confettiData.push({
        x: origin.x, y: origin.y + Math.random() * 2, z: origin.z + (Math.random() - 0.5) * 3,
        vx: (Math.random() - 0.5) * 5 - side * Math.random() * 2,
        vy: Math.random() * 6 + 2,
        vz: (Math.random() - 0.5) * 8,
      });
    }
    positions.needsUpdate = true;
    colorAttr.needsUpdate = true;
    this.confetti.material.opacity = 1;
    this.shake = 0.22;
    this.netPulse = 1;
  }

  updateConfetti(dt) {
    if (!this.confettiData || this.confetti.material.opacity <= 0) return;
    const positions = this.confetti.geometry.getAttribute('position');
    for (let i = 0; i < this.confettiData.length; i += 1) {
      const p = this.confettiData[i];
      p.vy -= 8.5 * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      if (p.y < 0.1) {
        p.y = 0.1;
        p.vy *= -0.25;
        p.vx *= 0.8;
        p.vz *= 0.8;
      }
      positions.setXYZ(i, p.x, p.y, p.z);
    }
    positions.needsUpdate = true;
    this.confetti.material.opacity = Math.max(0, this.confetti.material.opacity - dt * 0.22);
  }

  flashGoal() {
    this.addShake(0.18);
  }

  render() {
    this.renderer.render(this.scene, this.camera);
  }

  setQuality(quality) {
    this.quality = quality;
    const high = quality === 'high';
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, high ? 1.7 : 1));
    this.renderer.shadowMap.enabled = high;
    this.renderer.shadowMap.needsUpdate = true;
    this.resize();
  }
}

function finalPos(arr, teamIndex, index, kick, team) {
  const p = kick[index];
  const teamDir = teamIndex === 0 ? 1 : -1;
  const id = `${teamIndex}-${index}`;
  arr.push({
    id,
    index,
    team: teamIndex,
    teamIndex,
    teamObj: team,
    role: p.role,
    number: team.numbers[index],
    name: team.names[index],
    x: p.x * teamDir,
    z: p.z,
    dir: teamDir > 0 ? 0 : Math.PI,
  });
}

import {
  COURT, MATCH, PLAYER, FORMATION, DEPTH, ACTION, PHASE,
  clamp, lerp, angleLerp, rand, chance,
} from './constants.js';

const OUT_ROLES = ['LB', 'RB', 'CM', 'ST'];

export function createMatchState({ homeTeam, awayTeam, seed = Math.random() }) {
  let s = seed;
  const random = () => {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
  const players = [];
  for (let t = 0; t < 2; t += 1) {
    const team = t === 0 ? homeTeam : awayTeam;
    const roles = ['GK', 'LB', 'RB', 'CM', 'ST'];
    roles.forEach((role, i) => {
      players.push({
        id: `${t}-${i}`,
        index: i,
        team: t,
        role,
        number: team.numbers[i],
        name: team.names[i],
        skin: Math.floor(random() * 6),
        x: 0,
        z: 0,
        vx: 0,
        vz: 0,
        dir: t === 0 ? 0 : Math.PI,
        stamina: 100,
        speed: role === 'GK' ? 5.4 : 6.1 + random() * 0.7,
        action: ACTION.idle,
        actionT: 0,
        tackleCd: 0,
        switchCd: 0,
        charge: 0,
        holding: false,
        ai: { think: random() * 0.2, targetX: 0, targetZ: 0, sprint: false, intent: 'shape' },
        goals: 0,
        posHistory: [],
      });
    });
  }
  return {
    phase: PHASE.countdown,
    phaseT: MATCH.kickoffPause,
    clock: MATCH.halfSeconds,
    half: 1,
    score: [0, 0],
    attacks: [1, -1],
    players,
    ball: { x: 0, y: COURT.ballRadius, z: 0, vx: 0, vy: 0, vz: 0, owner: null, lastTouch: null, lastTeam: null, pickupLock: 0, rx: 0, rz: 0 },
    active: [null, null],
    human: [true, false],
    kickoffTeam: 0,
    lastGoalTeam: null,
    lastScorer: null,
    goalMinute: 0,
    stats: [
      { shots: 0, passes: 0, tackles: 0, saves: 0, possession: 0 },
      { shots: 0, passes: 0, tackles: 0, saves: 0, possession: 0 },
    ],
    possession: null,
    eventCount: 0,
    events: [],
    countdown: MATCH.kickoffPause,
    online: false,
    showcase: false,
    lastKick: 0,
    afterGoal: false,
  };
}

export class MatchSim {
  constructor({ homeTeam, awayTeam, remoteTeam = null, seed = Math.random(), online = false, difficulty = 1 }) {
    this.state = createMatchState({ homeTeam, awayTeam, seed });
    this.state.human = remoteTeam === null ? [true, false] : [true, true];
    this.state.online = online;
    this.remoteTeam = remoteTeam;
    this.difficulty = difficulty;
    this.inputs = [
      { mx: 0, mz: 0, sprint: false, shootHeld: false, shootDown: false, shootUp: false, pass: false, tackle: false, switch: false },
      { mx: 0, mz: 0, sprint: false, shootHeld: false, shootDown: false, shootUp: false, pass: false, tackle: false, switch: false },
    ];
    this.onEvent = null;
    this.resetPositions(this.state.kickoffTeam, true);
    this.setActive(0, this.state.players[8].id);
    this.setActive(1, this.state.players[3].id);
    this.emit('kickoff', { team: 0 });
    this.touchTimer = 0;
    this.possessionTimer = 0;
    this.aiTick = 0;
    this.lastCountdownShown = 4;
    this.kickoffStart = true;
  }

  attackDir(team) {
    return this.state.attacks[team];
  }

  ownGoalX(team) {
    return -this.attackDir(team) * COURT.halfL;
  }

  targetGoalX(team) {
    return this.attackDir(team) * COURT.halfL;
  }

  other(team) {
    return 1 - team;
  }

  playerById(id) {
    return this.state.players.find((p) => p.id === id);
  }

  setActive(team, id) {
    this.state.active[team] = id;
    const p = this.playerById(id);
    if (p) p.switchCd = 1.1;
  }

  emit(type, data = {}) {
    this.state.eventCount += 1;
    this.state.events.push({ type, ...data, id: this.state.eventCount });
    if (this.state.events.length > 30) this.state.events.shift();
    if (this.onEvent) this.onEvent(type, { ...data, id: this.state.eventCount });
  }

  drainEvents() {
    const events = this.state.events.slice();
    this.state.events.length = 0;
    return events;
  }

  setInput(team, input) {
    const t = this.inputs[team];
    t.mx = input.mx || 0;
    t.mz = input.mz || 0;
    t.sprint = !!input.sprint;
    t.shootHeld = !!input.shootHeld;
    t.shootDown = !!input.shootDown;
    t.shootUp = !!input.shootUp;
    t.pass = !!input.pass;
    t.tackle = !!input.tackle;
    t.switch = !!input.switch;
  }

  resetPositions(kickoffTeam, first = false) {
    const s = this.state;
    s.kickoffTeam = kickoffTeam;
    s.ball.x = 0;
    s.ball.y = COURT.ballRadius;
    s.ball.z = 0;
    s.ball.vx = 0;
    s.ball.vy = 0;
    s.ball.vz = 0;
    s.ball.owner = null;
    s.ball.lastTouch = null;
    s.ball.pickupLock = 0.15;
    s.players.forEach((p) => {
      p.vx = 0;
      p.vz = 0;
      p.stamina = Math.max(p.stamina, 55);
      p.action = ACTION.idle;
      p.actionT = 0;
      p.charge = 0;
      p.tackleCd = 0;
      p.switchCd = 0;
      p.holding = false;
      const dir = this.attackDir(p.team);
      const role = p.role;
      const mirror = p.team === 0 ? 1 : -1;
      if (role === 'GK') {
        p.x = -dir * (COURT.halfL - 1.3);
        p.z = 0;
      } else if (role === 'LB') {
        p.x = -dir * 8.0;
        p.z = mirror * -4.2;
      } else if (role === 'RB') {
        p.x = -dir * 8.0;
        p.z = mirror * 4.2;
      } else if (role === 'CM') {
        p.x = -dir * 3.1;
        p.z = mirror * 0.8;
      } else {
        p.x = dir * 1.1;
        p.z = mirror * -0.6;
      }
      if (p.team === kickoffTeam && role === 'ST') {
        p.x = -dir * 0.4;
        p.z = 0.35;
      }
      p.dir = dir > 0 ? 0 : Math.PI;
      p.goalSide = 0;
    });
    s.active = [s.players[8].id, s.players[3].id];
    if (first) {
      s.phase = PHASE.countdown;
      s.phaseT = MATCH.kickoffPause;
      s.countdown = MATCH.kickoffPause;
    }
  }

  kickOff(team) {
    this.resetPositions(team, false);
    this.state.phase = PHASE.countdown;
    this.state.phaseT = MATCH.kickoffPause;
    this.state.countdown = MATCH.kickoffPause;
    this.emit('kickoff', { team });
  }

  beginPlaying() {
    this.state.phase = PHASE.playing;
    this.state.phaseT = 0;
    this.emit('whistle', {});
  }

  endHalf() {
    const s = this.state;
    if (s.half === 1) {
      s.phase = PHASE.halftime;
      s.phaseT = MATCH.halftimePause;
      this.emit('halftime', { score: [...s.score] });
    } else {
      s.phase = PHASE.fulltime;
      s.phaseT = 0;
      this.emit('fulltime', { score: [...s.score], stats: s.stats });
    }
  }

  startSecondHalf() {
    const s = this.state;
    s.half = 2;
    s.clock = MATCH.halfSeconds;
    s.attacks = [-s.attacks[0], -s.attacks[1]];
    s.kickoffTeam = 1;
    this.resetPositions(1, false);
    s.phase = PHASE.countdown;
    s.phaseT = MATCH.kickoffPause;
    s.countdown = MATCH.kickoffPause;
    this.emit('secondhalf', {});
  }

  update(dt) {
    const s = this.state;
    s.phaseT = Math.max(0, s.phaseT - dt);
    if (s.phase === PHASE.countdown) {
      const prev = Math.ceil(s.phaseT);
      s.countdown = s.phaseT;
      this.emitTick(prev);
      if (s.phaseT <= 0) this.beginPlaying();
      this.updateIdlePlayers(dt);
      this.updateBall(dt);
      this.updateTimers(dt);
      return;
    }
    if (s.phase === PHASE.goal) {
      this.updateBall(dt);
      if (s.phaseT <= 0) {
        const conceding = 1 - s.lastGoalTeam;
        this.kickOff(conceding);
        this.state.afterGoal = false;
      }
      this.updateTimers(dt);
      return;
    }
    if (s.phase === PHASE.halftime) {
      if (s.phaseT <= 0) this.startSecondHalf();
      this.updateIdlePlayers(dt);
      this.updateTimers(dt);
      return;
    }
    if (s.phase !== PHASE.playing) {
      this.updateTimers(dt);
      return;
    }

    s.clock = Math.max(0, s.clock - dt);
    if (s.clock <= 0) {
      this.endHalf();
      return;
    }

    this.touchTimer += dt;
    this.possessionTimer += dt;
    if (s.possession !== null) s.stats[s.possession].possession += dt;

    this.updateHumanControl(dt);
    this.updateAI(dt);
    this.updateMovements(dt);
    this.resolvePlayerCollisions();
    this.updatePossession(dt);
    this.updateBall(dt);
    this.checkGoal();
    this.updateTimers(dt);
    this.debugPossession(dt);
  }

  emitTick(prev) {
    const s = this.state;
    const now = Math.ceil(s.phaseT * 10) / 10;
    if (s.phase === PHASE.countdown) {
      const n = Math.ceil(s.phaseT);
      if (n !== this.lastCountdownShown && n > 0 && n <= 3) {
        this.lastCountdownShown = n;
        this.emit('countdown', { n });
      }
    }
  }

  updateTimers(dt) {
    const s = this.state;
    for (const p of s.players) {
      p.actionT = Math.max(0, p.actionT - dt);
      p.tackleCd = Math.max(0, p.tackleCd - dt);
      p.switchCd = Math.max(0, p.switchCd - dt);
      if (p.action === ACTION.kick || p.action === ACTION.pass || p.action === ACTION.shoot) {
        if (p.actionT <= 0) p.action = ACTION.idle;
      }
      if (p.action === ACTION.slide || p.action === ACTION.hurt || p.action === ACTION.dive) {
        if (p.actionT <= 0) {
          p.action = ACTION.idle;
          if (p.role === 'GK') p.goalSide = 0;
        }
      }
      if (!p.holding) p.charge = Math.max(0, p.charge - dt * 0.4);
    }
    this.touchTimer += dt;
    if (this.touchTimer > 0.4) {
      this.touchTimer = 0;
      this.updateAutoSwitch();
    }
  }

  debugPossession() {}

  updateIdlePlayers(dt) {
    for (const p of this.state.players) {
      p.vx *= Math.exp(-8 * dt);
      p.vz *= Math.exp(-8 * dt);
      p.x += p.vx * dt;
      p.z += p.vz * dt;
      p.stamina = Math.min(100, p.stamina + dt * 14);
      if (p.actionT <= 0 && p.action !== ACTION.idle) p.action = ACTION.idle;
      if (p.actionT > 0) p.actionT -= dt;
    }
  }

  updateAutoSwitch() {
    const s = this.state;
    for (let team = 0; team < 2; team += 1) {
      if (!s.human[team]) continue;
      const active = this.playerById(s.active[team]);
      if (!active || active.switchCd > 0) continue;
      const ball = s.ball;
      if (ball.owner) {
        const owner = this.playerById(ball.owner);
        if (owner && owner.team === team) {
          if (active.id !== owner.id && active.role !== 'GK') {
            this.setActive(team, owner.id);
          }
        } else if (active.id !== owner.id) {
          const nearest = this.nearestToBall(team, true);
          if (nearest && Math.hypot(nearest.x - active.x, nearest.z - active.z) > 4.5) {
            this.setActive(team, nearest.id);
          }
        }
      } else {
        const nearest = this.nearestToBall(team, true);
        if (nearest && Math.hypot(nearest.x - active.x, nearest.z - active.z) > 5) {
          this.setActive(team, nearest.id);
        }
      }
    }
  }

  nearestToBall(team, excludeGk = false) {
    let best = null;
    let bestD = Infinity;
    for (const p of this.state.players) {
      if (p.team !== team) continue;
      if (excludeGk && p.role === 'GK') continue;
      if (p.stun > 0) continue;
      const d = Math.hypot(p.x - this.state.ball.x, p.z - this.state.ball.z);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }

  nearestOpponent(team, x, z) {
    let best = null;
    let bestD = Infinity;
    for (const p of this.state.players) {
      if (p.team === team) continue;
      const d = Math.hypot(p.x - x, p.z - z);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }

  updateHumanControl(dt) {
    const s = this.state;
    for (let team = 0; team < 2; team += 1) {
      if (!s.human[team]) continue;
      const player = this.playerById(s.active[team]);
      if (!player) continue;
      const inp = this.inputs[team];
      if (inp.switch) this.manualSwitch(team);
      if (player.action === ACTION.slide || player.action === ACTION.hurt) continue;
      if (s.ball.owner === player.id) {
        if (inp.shootDown) player.charge = 0.16;
        if (inp.shootHeld) player.charge = Math.min(1, player.charge + dt * 1.45);
        if (inp.shootUp) {
          const power = player.charge || 0.16;
          this.doShot(player, power);
          player.charge = 0;
        } else if (!inp.shootHeld && player.charge > 0.12) {
          const power = player.charge;
          this.doShot(player, power);
          player.charge = 0;
        }
        if (inp.pass) this.doPass(player);
        if (inp.tackle) this.startSlide(player);
        const mag = Math.hypot(inp.mx, inp.mz);
        player.moveX = mag > 0.12 ? inp.mx : 0;
        player.moveZ = mag > 0.12 ? inp.mz : 0;
        player.wantSprint = inp.sprint && mag > 0.15;
      } else {
        player.charge = 0;
        const mag = Math.hypot(inp.mx, inp.mz);
        player.moveX = mag > 0.12 ? inp.mx : 0;
        player.moveZ = mag > 0.12 ? inp.mz : 0;
        player.wantSprint = inp.sprint && mag > 0.15;
        if (inp.tackle) this.startSlide(player);
        if (inp.shootDown) {
          // no ball: quick close-down tackle instead of shooting
          this.startSlide(player);
        }
      }
    }
  }

  manualSwitch(team) {
    const s = this.state;
    const current = this.playerById(s.active[team]);
    const candidates = s.players.filter((p) => p.team === team).sort((a, b) => {
      const da = Math.hypot(a.x - s.ball.x, a.z - s.ball.z);
      const db = Math.hypot(b.x - s.ball.x, b.z - s.ball.z);
      return da - db;
    });
    if (candidates.length < 2) return;
    let idx = candidates.findIndex((p) => p.id === current?.id);
    idx = (idx + 1) % candidates.length;
    this.setActive(team, candidates[idx].id);
    this.emit('switch', { team });
  }

  updateAI(dt) {
    const s = this.state;
    this.aiTick += dt;
    for (const p of s.players) {
      if (!s.human[p.team] && p.id === s.active[p.team]) {
        // Every AI-controlled active player acts via normal AI.
      }
      const inp = this.inputs[p.team];
      const isHumanActive = s.human[p.team] && s.active[p.team] === p.id;
      if (isHumanActive) continue;
      this.updateAIPlayer(p, dt);
    }
  }

  teamStrategy(team) {
    const s = this.state;
    const ball = s.ball;
    const dir = this.attackDir(team);
    const owner = ball.owner ? this.playerById(ball.owner) : null;
    const hasBall = owner && owner.team === team;
    const ballLoose = !owner;
    const distanceToOwnGoal = Math.hypot(ball.x - this.ownGoalX(team), ball.z);
    let urgency = 0;
    if (!hasBall) urgency = distanceToOwnGoal < 14 ? 1 : 0.55;
    return { dir, owner, hasBall, ballLoose, urgency };
  }

  formationPosition(p, ballX, ballZ) {
    const team = p.team;
    const dir = this.attackDir(team);
    const side = p.team === 0 ? 1 : 1;
    const ownGoalX = this.ownGoalX(team);
    if (p.role === 'GK') {
      return { x: ownGoalX + dir * 0.95, z: clamp(ballZ * 0.22, -1.15, 1.15) };
    }
    const base = FORMATION[p.role] || FORMATION.CM;
    let x = ownGoalX + dir * (base.depth + clamp((ballX - ownGoalX) * dir * 0.2, -2, 5));
    let z = base.z * (p.team === 0 ? 1 : 1) + ballZ * 0.18;
    if (p.role === 'LB') z = -4.4 + ballZ * 0.2;
    if (p.role === 'RB') z = 4.4 + ballZ * 0.2;
    if (p.role === 'CM') z = ballZ * 0.35;
    if (p.role === 'ST') z = ballZ * 0.48;
    x = clamp(x, -COURT.halfL + 2, COURT.halfL - 2);
    z = clamp(z, -COURT.halfW + 1.1, COURT.halfW - 1.1);
    return { x, z };
  }

  updateAIPlayer(p, dt) {
    const s = this.state;
    const ai = p.ai;
    ai.think -= dt;
    const strategy = this.teamStrategy(p.team);
    const ball = s.ball;
    const dir = strategy.dir;
    const owner = strategy.owner;
    const hasPossession = strategy.hasBall;
    const teamMates = s.players.filter((q) => q.team === p.team);
    const outfield = teamMates.filter((q) => q.role !== 'GK');
    const distanceBall = Math.hypot(p.x - ball.x, p.z - ball.z);
    const ownGoalX = this.ownGoalX(p.team);
    const targetGoalX = this.targetGoalX(p.team);
    const isClosest = outfield.reduce((best, q) => {
      const d = Math.hypot(q.x - ball.x, q.z - ball.z);
      return d < best.d ? { p: q, d } : best;
    }, { p: null, d: Infinity }).p === p;
    const secondClosest = outfield
      .filter((q) => q.id !== p.id)
      .sort((a, b) => Math.hypot(a.x - ball.x, a.z - ball.z) - Math.hypot(b.x - ball.x, b.z - ball.z))[0];
    const isSecond = secondClosest && secondClosest.id === p.id;
    const ballOwnerPlayer = owner;

    p.wantSprint = false;
    p.moveX = 0;
    p.moveZ = 0;

    if (p.role === 'GK') {
      this.gkAI(p, dt);
      return;
    }

    if (owner && owner.id === p.id) {
      this.carrierAI(p, dt);
      return;
    }

    if (ai.think <= 0) {
      ai.think = 0.12 + Math.random() * 0.15;
      const base = this.formationPosition(p, ball.x, ball.z);
      let targetX = base.x;
      let targetZ = base.z;
      let sprint = false;
      let intent = 'shape';

      if (!hasPossession && strategy.ballLoose) {
        if (isClosest) {
          const lead = 0.13;
          targetX = ball.x + ball.vx * lead;
          targetZ = ball.z + ball.vz * lead;
          sprint = distanceBall > 4;
          intent = 'chase';
        } else if (isSecond) {
          targetX = lerp(ball.x, ownGoalX, 0.22);
          targetZ = lerp(ball.z, 0, 0.28);
          sprint = distanceBall > 8;
          intent = 'cover';
        }
      } else if (!hasPossession && owner.team !== p.team) {
        if (isClosest) {
          const ox = owner.x + owner.vx * 0.18;
          const oz = owner.z + owner.vz * 0.18;
          targetX = ox;
          targetZ = oz;
          sprint = distanceBall > 3;
          intent = 'press';
          if (distanceBall < 1.45 && p.tackleCd <= 0 && chance(0.014)) this.startSlide(p);
        } else if (isSecond) {
          targetX = lerp(owner.x, ownGoalX, 0.3);
          targetZ = lerp(owner.z, 0, 0.5);
          intent = 'cover';
        } else {
          const mark = this.nearestOpponent(p.team, p.x, p.z);
          if (mark && Math.hypot(mark.x - ownGoalX, mark.z) < 15) {
            targetX = lerp(mark.x, ownGoalX, 0.18);
            targetZ = lerp(mark.z, 0, 0.1);
          }
          intent = 'mark';
        }
      } else if (hasPossession) {
        if (isClosest) {
          targetX = ball.x + dir * 2.2;
          targetZ = ball.z + (p.role === 'ST' ? -1.2 : 1.2);
          sprint = true;
          intent = 'support';
        } else {
          const run = p.role === 'ST' ? 4.5 : p.role === 'CM' ? 2.5 : 1.2;
          targetX = clamp(base.x + dir * run, -COURT.halfL + 2, COURT.halfL - 2);
          targetZ = base.z + (p.role === 'ST' ? Math.sin(s.clock * 0.35) * 1.8 : 0);
          sprint = p.role === 'ST' || (p.role === 'CM' && distanceBall < 10);
          intent = 'attack';
        }
      }

      ai.targetX = targetX;
      ai.targetZ = targetZ;
      ai.sprint = sprint;
      ai.intent = intent;
    }

    const dx = ai.targetX - p.x;
    const dz = ai.targetZ - p.z;
    const d = Math.hypot(dx, dz);
    if (d > 0.18) {
      p.moveX = dx / d;
      p.moveZ = dz / d;
      if (d < 0.8) {
        p.moveX *= 0.55;
        p.moveZ *= 0.55;
      }
    }
    p.wantSprint = ai.sprint && p.stamina > 18;
  }

  carrierAI(p, dt) {
    const s = this.state;
    const ball = s.ball;
    const dir = this.attackDir(p.team);
    const goalX = this.targetGoalX(p.team);
    const distGoal = Math.hypot(goalX - p.x, p.z);
    const pressure = this.nearestOpponent(p.team, p.x, p.z);
    const pressureDist = pressure ? Math.hypot(pressure.x - p.x, pressure.z - p.z) : 99;
    const base = this.formationPosition(p, ball.x, ball.z);
    p.ai.think -= dt;

    // decision to shoot or pass
    if (p.ai.think <= 0) {
      p.ai.think = 0.15;
      const goalOpen = Math.abs(p.z) < 7.2;
      if (distGoal < 9.5 && goalOpen && chance(0.018 + (distGoal < 6 ? 0.012 : 0))) {
        const aimZ = clamp(p.z * 0.45 + rand(-1.1, 1.1), -COURT.goalHalf + 0.3, COURT.goalHalf - 0.3);
        this.doShot(p, clamp(0.65 + (9.5 - distGoal) * 0.04, 0.55, 0.95), aimZ);
        return;
      }
      if (pressureDist < 2.8 && chance(0.05)) {
        const target = this.findPassTarget(p);
        if (target) {
          this.doPass(p, target);
          return;
        }
      }
      if (pressureDist < 2.1 && chance(0.025)) {
        const goalAimZ = p.z > 0 ? COURT.goalHalf - 0.45 : -COURT.goalHalf + 0.45;
        this.doShot(p, 0.55, goalAimZ);
        return;
      }
    }

    let targetX = goalX - dir * 1.8;
    let targetZ = clamp(p.z * 0.55 + rand(-0.2, 0.2), -COURT.halfW + 2, COURT.halfW - 2);
    if (pressure) {
      const px = p.x - pressure.x;
      const pz = p.z - pressure.z;
      const pd = Math.hypot(px, pz) || 1;
      targetX += (px / pd) * 1.2;
      targetZ += (pz / pd) * 2.5;
    }
    if (Math.abs(p.z) > COURT.halfW - 2.2) targetZ = Math.sign(p.z) * (COURT.halfW - 3.2);
    targetX = clamp(targetX, -COURT.halfL + 1.5, COURT.halfL - 0.9);
    targetZ = clamp(targetZ, -COURT.halfW + 1.2, COURT.halfW - 1.2);
    const dx = targetX - p.x;
    const dz = targetZ - p.z;
    const d = Math.hypot(dx, dz) || 1;
    p.moveX = dx / d;
    p.moveZ = dz / d;
    p.wantSprint = p.stamina > 25 && distGoal > 4;
    if (pressureDist < 1.2 && p.tackleCd <= 0 && chance(0.04)) {
      // held ball under pressure: shield rather than panic
    }
  }

  findPassTarget(p) {
    const s = this.state;
    const dir = this.attackDir(p.team);
    let best = null;
    let bestScore = -Infinity;
    for (const mate of s.players) {
      if (mate.team !== p.team || mate.id === p.id || mate.role === 'GK') continue;
      const dx = mate.x - p.x;
      const dz = mate.z - p.z;
      const d = Math.hypot(dx, dz);
      if (d < 2 || d > 18) continue;
      const forward = (dx * dir - Math.abs(dz) * 0.2) / Math.max(d, 1);
      const goalProx = (mate.x * dir) / COURT.halfL;
      const nearest = this.nearestOpponent(p.team, mate.x, mate.z);
      const open = nearest ? Math.hypot(nearest.x - mate.x, nearest.z - mate.z) : 10;
      const score = forward * 2.2 + goalProx * 1.6 + open * 0.15 - d * 0.05;
      if (score > bestScore) {
        bestScore = score;
        best = mate;
      }
    }
    return best;
  }

  gkAI(p, dt) {
    const s = this.state;
    const ball = s.ball;
    const dir = this.attackDir(p.team);
    const goalX = this.ownGoalX(p.team);
    const lineX = goalX + dir * 0.75;
    const ballInOwnHalf = (ball.x - goalX) * dir < 11;
    const ballNear = Math.hypot(ball.x - p.x, ball.z - p.z) < 9.5;
    let targetX = lineX;
    let targetZ = clamp(ball.z * 0.45, -1.25, 1.25);
    if (ballInOwnHalf && ballNear && !ball.owner) {
      targetX = goalX + dir * clamp((ball.x - goalX) * dir * 0.34, 0.5, 4.5);
      targetZ = clamp(ball.z * 0.65, -2.6, 2.6);
    }
    if (ball.owner) {
      const owner = this.playerById(ball.owner);
      if (owner && owner.team !== p.team && ballNear) {
        targetX = goalX + dir * clamp((ball.x - goalX) * dir * 0.18, 0.5, 2.2);
        targetZ = clamp(ball.z * 0.72, -1.8, 1.8);
      }
    }
    // anticipate shots
    if (!ball.owner && Math.hypot(ball.vx, ball.vz) > 13) {
      const coming = (ball.x - goalX) * -dir;
      if (coming > 0 && coming < 15) {
        const t = Math.max(0.05, Math.min(0.8, Math.abs((goalX - ball.x) / (ball.vx || 0.01))));
        const predZ = ball.z + ball.vz * t;
        if (Math.abs(predZ) < 4.2) {
          targetZ = clamp(predZ, -COURT.goalHalf + 0.25, COURT.goalHalf - 0.25);
          targetX = lineX;
          if (p.action !== ACTION.dive && Math.abs(predZ - p.z) > 0.75 && chance(0.2)) {
            p.action = ACTION.dive;
            p.actionT = 0.55;
            p.goalSide = Math.sign(predZ - p.z) || 1;
          }
        }
      }
    }
    const dx = targetX - p.x;
    const dz = targetZ - p.z;
    const d = Math.hypot(dx, dz);
    if (d > 0.12) {
      p.moveX = dx / d;
      p.moveZ = dz / d;
    }
    p.wantSprint = d > 1.6;
    if (p.action === ACTION.dive) {
      p.moveX *= 0.2;
      p.moveZ *= 0.2;
    }
    if (ball.owner === p.id) {
      // hold for a beat then distribute
      p.holding = true;
      p.holdTimer = (p.holdTimer || 0) + dt;
      p.moveX *= 0.2;
      p.moveZ *= 0.2;
      if (p.holdTimer > 1.0) {
        const target = this.findPassTarget(p) || s.players.find((q) => q.team === p.team && q.id !== p.id);
        if (target) this.doPass(p, target, 1.15);
        else this.doShot(p, 0.7);
        p.holdTimer = 0;
        p.holding = false;
      }
    }
  }

  updateMovements(dt) {
    const s = this.state;
    for (const p of s.players) {
      if (p.action === ACTION.slide) {
        p.vx *= Math.exp(-3.4 * dt);
        p.vz *= Math.exp(-3.4 * dt);
        p.x += p.vx * dt;
        p.z += p.vz * dt;
        p.stamina = Math.max(0, p.stamina - dt * 8);
        this.constrainPlayer(p);
        continue;
      }
      if (p.action === ACTION.hurt) {
        p.vx *= Math.exp(-10 * dt);
        p.vz *= Math.exp(-10 * dt);
        p.x += p.vx * dt;
        p.z += p.vz * dt;
        this.constrainPlayer(p);
        continue;
      }
      let mx = p.moveX || 0;
      let mz = p.moveZ || 0;
      const mag = Math.hypot(mx, mz);
      if (mag > 1) {
        mx /= mag;
        mz /= mag;
      }
      const hasBall = s.ball.owner === p.id;
      const isGK = p.role === 'GK';
      let maxSpeed = p.speed * (p.wantSprint && p.stamina > 4 ? 1.34 : 1);
      if (hasBall) maxSpeed *= 0.91;
      if (isGK) maxSpeed *= 1.03;
      if (p.stamina <= 4) maxSpeed *= 0.85;
      if (mag > 0.1) {
        const turn = isGK ? 9 : 15;
        const targetVx = mx * maxSpeed;
        const targetVz = mz * maxSpeed;
        p.vx = lerp(p.vx, targetVx, 1 - Math.exp(-turn * dt));
        p.vz = lerp(p.vz, targetVz, 1 - Math.exp(-turn * dt));
        const desired = Math.atan2(mz, mx);
        p.dir = angleLerp(p.dir, desired, 1 - Math.exp(-12 * dt));
      } else {
        p.vx *= Math.exp(-8 * dt);
        p.vz *= Math.exp(-8 * dt);
      }
      p.x += p.vx * dt;
      p.z += p.vz * dt;
      const sprinting = p.wantSprint && mag > 0.1 && p.stamina > 4;
      p.stamina = clamp(p.stamina + (sprinting ? -dt * 17 : dt * 8.5), 0, 100);
      this.constrainPlayer(p);
      if (p.charge > 0) p.charge = Math.min(1, p.charge + dt * 0.0);
    }
  }

  constrainPlayer(p) {
    const margin = 0.55;
    p.x = clamp(p.x, -COURT.halfL + margin, COURT.halfL - margin);
    p.z = clamp(p.z, -COURT.halfW + margin, COURT.halfW - margin);
    // goal area allows goalkeeper a little extra
    if (p.role === 'GK') {
      const own = this.ownGoalX(p.team);
      if (Math.abs(p.x - own) < 1.4 && Math.abs(p.z) < 1.55) {
        p.x = clamp(p.x, Math.min(own, own + this.attackDir(p.team) * 1.5), Math.max(own, own + this.attackDir(p.team) * 1.5));
      }
    }
  }

  resolvePlayerCollisions() {
    const ps = this.state.players;
    for (let i = 0; i < ps.length; i += 1) {
      for (let j = i + 1; j < ps.length; j += 1) {
        const a = ps[i];
        const b = ps[j];
        let dx = b.x - a.x;
        let dz = b.z - a.z;
        let d = Math.hypot(dx, dz);
        const minD = PLAYER.radius * 2;
        if (d > 0.0001 && d < minD) {
          const push = (minD - d) * 0.5;
          dx /= d;
          dz /= d;
          a.x -= dx * push;
          a.z -= dz * push;
          b.x += dx * push;
          b.z += dz * push;
          if (a.action === ACTION.slide && b.action !== ACTION.slide && s2(b)) {
            b.action = ACTION.hurt;
            b.actionT = 0.24;
            b.vx += dx * 2;
            b.vz += dz * 2;
          }
          if (b.action === ACTION.slide && a.action !== ACTION.slide) {
            a.action = ACTION.hurt;
            a.actionT = 0.24;
            a.vx -= dx * 2;
            a.vz -= dz * 2;
          }
        }
      }
    }
  }

  updatePossession(dt) {
    const s = this.state;
    const ball = s.ball;
    ball.pickupLock = Math.max(0, ball.pickupLock - dt);
    if (ball.owner) {
      const owner = this.playerById(ball.owner);
      if (!owner) {
        ball.owner = null;
        return;
      }
      if (owner.action === ACTION.slide || owner.action === ACTION.hurt) {
        this.releaseBall(owner, 0.5);
        return;
      }
      const speed = Math.hypot(owner.vx, owner.vz);
      const dribble = 0.55 + clamp(speed * 0.04, 0, 0.16);
      const targetX = owner.x + Math.cos(owner.dir) * dribble;
      const targetZ = owner.z + Math.sin(owner.dir) * dribble;
      ball.x = lerp(ball.x, targetX, 1 - Math.exp(-22 * dt));
      ball.z = lerp(ball.z, targetZ, 1 - Math.exp(-22 * dt));
      ball.y = COURT.ballRadius + Math.abs(Math.sin(performance.now() * 0.016)) * 0.015;
      ball.vx = owner.vx;
      ball.vz = owner.vz;
      ball.vy = 0;
      this.checkTackles(owner, dt);
      return;
    }
    if (ball.pickupLock > 0) return;
    if (ball.y > 0.75) return;
    let best = null;
    let bestD = 0.72;
    for (const p of s.players) {
      if (p.action === ACTION.slide || p.action === ACTION.hurt) continue;
      const d = Math.hypot(p.x - ball.x, p.z - ball.z);
      const reach = p.role === 'GK' ? 1.18 : 0.74;
      if (d < Math.min(bestD, reach)) {
        bestD = d;
        best = p;
      }
    }
    if (best) {
      const ballSpeed = Math.hypot(ball.vx, ball.vz);
      if (ballSpeed > 17 && best.role !== 'GK' && chance(0.45)) {
        // first touch is heavy: deflect instead of instant control
        const dx = ball.x - best.x;
        const dz = ball.z - best.z;
        const d = Math.hypot(dx, dz) || 1;
        ball.vx = (dx / d) * ballSpeed * 0.42 + best.vx * 0.3;
        ball.vz = (dz / d) * ballSpeed * 0.42 + best.vz * 0.3;
        ball.lastTouch = best.id;
        ball.lastTeam = best.team;
        ball.pickupLock = 0.18;
        return;
      }
      this.takePossession(best);
    }
  }

  takePossession(p) {
    const s = this.state;
    s.ball.owner = p.id;
    s.ball.lastTouch = p.id;
    s.ball.lastTeam = p.team;
    s.possession = p.team;
    p.holding = p.role === 'GK';
    p.charge = 0;
    s.ball.vx = p.vx;
    s.ball.vz = p.vz;
    s.ball.y = COURT.ballRadius;
    if (s.human[p.team] && s.active[p.team] !== p.id) {
      // if a teammate wins the ball, give control to them only if close to user
      const active = this.playerById(s.active[p.team]);
      if (active && Math.hypot(active.x - p.x, active.z - p.z) < 6) this.setActive(p.team, p.id);
    }
  }

  releaseBall(p, power = 0.4) {
    const s = this.state;
    if (s.ball.owner !== p.id) return;
    s.ball.owner = null;
    s.ball.pickupLock = 0.3;
    const speed = Math.hypot(p.vx, p.vz);
    s.ball.vx = p.vx * 0.6 + Math.cos(p.dir) * power * 2;
    s.ball.vz = p.vz * 0.6 + Math.sin(p.dir) * power * 2;
    s.ball.vy = 0.4;
  }

  checkTackles(owner, dt) {
    const s = this.state;
    for (const p of s.players) {
      if (p.team === owner.team || p.action === ACTION.slide) continue;
      const d = Math.hypot(p.x - s.ball.x, p.z - s.ball.z);
      if (d < 0.76 && p.tackleCd <= 0 && chance(0.008)) {
        this.tackle(owner, p);
      }
    }
  }

  startSlide(p) {
    if (p.tackleCd > 0 || p.action === ACTION.slide || p.action === ACTION.hurt) return;
    if (p.role === 'GK') return;
    p.action = ACTION.slide;
    p.actionT = 0.5;
    p.tackleCd = 1.25;
    p.vx = Math.cos(p.dir) * 9.2;
    p.vz = Math.sin(p.dir) * 9.2;
    p.stamina = Math.max(0, p.stamina - 5);
    this.emit('tackle', { team: p.team, x: p.x, z: p.z });
    const owner = this.state.ball.owner ? this.playerById(this.state.ball.owner) : null;
    if (owner && owner.team !== p.team) {
      const d = Math.hypot(owner.x - p.x, owner.z - p.z);
      if (d < 1.9) {
        this.tackle(owner, p);
      }
    } else if (!owner) {
      const bd = Math.hypot(this.state.ball.x - p.x, this.state.ball.z - p.z);
      if (bd < 1.1) {
        this.state.ball.vx = Math.cos(p.dir) * 7 + p.vx * 0.2;
        this.state.ball.vz = Math.sin(p.dir) * 7 + p.vz * 0.2;
        this.state.ball.lastTouch = p.id;
        this.state.ball.lastTeam = p.team;
        this.state.ball.pickupLock = 0.25;
      }
    }
  }

  tackle(owner, tackler) {
    const s = this.state;
    const diff = Math.hypot(owner.x - tackler.x, owner.z - tackler.z);
    if (diff > 2.1) return;
    const winChance = clamp(0.62 - diff * 0.12 + (tackler.stamina - owner.stamina) * 0.002, 0.25, 0.88);
    if (chance(winChance)) {
      s.ball.owner = null;
      const angle = Math.atan2(owner.z - tackler.z, owner.x - tackler.x);
      s.ball.vx = Math.cos(angle) * 3.2 + tackler.vx * 0.4;
      s.ball.vz = Math.sin(angle) * 3.2 + tackler.vz * 0.4;
      s.ball.vy = 0.8;
      s.ball.pickupLock = 0.08;
      s.ball.lastTouch = tackler.id;
      s.ball.lastTeam = tackler.team;
      owner.action = ACTION.hurt;
      owner.actionT = 0.28;
      tackler.action = ACTION.slide;
      tackler.actionT = Math.max(tackler.actionT, 0.28);
      s.stats[tackler.team].tackles += 1;
      this.emit('tackle', { team: tackler.team, x: tackler.x, z: tackler.z, won: true });
      // tackler recovers the loose ball if close
      if (chance(0.55)) {
        s.ball.owner = tackler.id;
        s.ball.lastTouch = tackler.id;
        tackler.action = ACTION.idle;
        tackler.actionT = 0;
      }
    } else {
      owner.action = ACTION.hurt;
      owner.actionT = 0.15;
      tackler.action = ACTION.slide;
      tackler.actionT = 0.55;
      this.emit('tackle', { team: tackler.team, x: tackler.x, z: tackler.z, won: false });
    }
  }

  doPass(p, target = null, powerScale = 1) {
    const s = this.state;
    if (s.ball.owner !== p.id) return;
    if (p.action === ACTION.slide) return;
    const mate = target || this.findPassTarget(p);
    if (!mate) {
      this.doShot(p, 0.42);
      return;
    }
    const lead = Math.max(0.12, Math.hypot(mate.x - p.x, mate.z - p.z) / 22);
    const tx = mate.x + mate.vx * lead;
    const tz = mate.z + mate.vz * lead;
    let dx = tx - p.x;
    let dz = tz - p.z;
    const d = Math.hypot(dx, dz) || 1;
    dx /= d;
    dz /= d;
    const speed = clamp(d * 1.35 + 5.5, 9.5, 21) * powerScale;
    s.ball.owner = null;
    s.ball.pickupLock = 0.18;
    s.ball.vx = dx * speed;
    s.ball.vz = dz * speed;
    s.ball.vy = Math.min(2.2, 0.7 + d * 0.035);
    s.ball.y = 0.22;
    s.ball.lastTouch = p.id;
    s.ball.lastTeam = p.team;
    p.action = ACTION.pass;
    p.actionT = 0.24;
    p.charge = 0;
    s.stats[p.team].passes += 1;
    p.passTarget = mate.id;
    this.emit('pass', { team: p.team, x: p.x, z: p.z });
  }

  doShot(p, power = 0.7, aimZ = null) {
    const s = this.state;
    if (s.ball.owner !== p.id) return;
    const dir = this.attackDir(p.team);
    const goalX = this.targetGoalX(p.team);
    const zAim = aimZ === null
      ? clamp(p.z * 0.45 + rand(-1.2, 1.2), -COURT.goalHalf + 0.25, COURT.goalHalf - 0.25)
      : aimZ;
    const dx = goalX - p.x;
    const dz = zAim - p.z;
    const d = Math.hypot(dx, dz) || 1;
    const spread = (1 - power) * 0.12 + 0.02;
    const aimX = dx / d;
    const aimZv = dz / d + rand(-spread, spread);
    const norm = Math.hypot(aimX, aimZv) || 1;
    const speed = 19 + power * 12;
    s.ball.owner = null;
    s.ball.pickupLock = 0.24;
    s.ball.vx = (aimX / norm) * speed;
    s.ball.vz = (aimZv / norm) * speed;
    s.ball.vy = 1.2 + power * 3.4;
    s.ball.y = 0.26;
    s.ball.lastTouch = p.id;
    s.ball.lastTeam = p.team;
    p.action = ACTION.shoot;
    p.actionT = 0.32;
    p.charge = 0;
    s.stats[p.team].shots += 1;
    this.emit('shot', { team: p.team, power, player: p.name, x: p.x, z: p.z });
  }

  updateBall(dt) {
    const s = this.state;
    const b = s.ball;
    if (b.owner) return;
    if (b.pickupLock < 0) b.pickupLock = 0;
    const gravity = 15.5;
    const rolling = b.y <= COURT.ballRadius + 0.012;
    if (!rolling) {
      b.vy -= gravity * dt;
    }
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.z += b.vz * dt;
    b.rx += b.vz * dt * 2.8;
    b.rz -= b.vx * dt * 2.8;
    if (b.y <= COURT.ballRadius) {
      b.y = COURT.ballRadius;
      if (b.vy < -0.7) {
        b.vy = -b.vy * 0.54;
        if (Math.abs(b.vy) < 0.2) b.vy = 0;
        this.emit('bounce', { x: b.x, z: b.z });
      } else {
        b.vy = 0;
      }
    }
    const friction = rolling ? Math.exp(-0.78 * dt) : Math.exp(-0.09 * dt);
    b.vx *= friction;
    b.vz *= friction;

    // side walls
    const wallX = COURT.wallL;
    const wallZ = COURT.wallW;
    if (Math.abs(b.z) > wallZ - COURT.ballRadius) {
      b.z = Math.sign(b.z) * (wallZ - COURT.ballRadius);
      b.vz *= -0.72;
      b.vx *= 0.94;
      b.lastTeam = null;
      this.emit('wall', { x: b.x, z: b.z });
    }
    // end walls / goal interiors
    const inMouth = Math.abs(b.z) < COURT.goalHalf + 0.05 && b.y < COURT.goalHeight + 0.15;
    if (Math.abs(b.x) > wallX - COURT.ballRadius) {
      if (!inMouth) {
        b.x = Math.sign(b.x) * (wallX - COURT.ballRadius);
        b.vx *= -0.68;
        b.vz *= 0.94;
        b.lastTeam = null;
        this.emit('wall', { x: b.x, z: b.z });
      } else if (Math.abs(b.x) > wallX + COURT.netDepth) {
        b.x = Math.sign(b.x) * (wallX + COURT.netDepth);
        b.vx *= -0.3;
        b.vz *= 0.8;
        b.vy = Math.abs(b.vy) * 0.3;
      }
    }
    // goal posts
    for (const side of [-1, 1]) {
      const px = side * (COURT.halfL + 0.35);
      for (const z of [-COURT.goalHalf, COURT.goalHalf]) {
        const dx = b.x - px;
        const dz = b.z - z;
        const d = Math.hypot(dx, dz);
        const rr = COURT.ballRadius + 0.07;
        if (d < rr && d > 0.001) {
          const nx = dx / d;
          const nz = dz / d;
          b.x = px + nx * rr;
          b.z = z + nz * rr;
          const dot = b.vx * nx + b.vz * nz;
          b.vx = (b.vx - 2 * dot * nx) * 0.7;
          b.vz = (b.vz - 2 * dot * nz) * 0.7;
          this.emit('post', { x: b.x, z: b.z });
        }
      }
    }
    // crossbar (rough)
    if (b.y > COURT.goalHeight - 0.08 && b.y < COURT.goalHeight + 0.1) {
      for (const side of [-1, 1]) {
        const px = side * (COURT.halfL + 0.35);
        if (Math.abs(b.x - px) < 0.2 && Math.abs(b.z) < COURT.goalHalf) {
          b.vy = -Math.abs(b.vy) * 0.45 - 0.4;
          b.y = COURT.goalHeight - 0.11;
          this.emit('post', { x: b.x, z: b.z });
        }
      }
    }
    // ball-player deflections
    for (const p of s.players) {
      if (p.id === b.lastTouch || b.y > 1.35) continue;
      const dx = b.x - p.x;
      const dz = b.z - p.z;
      const d = Math.hypot(dx, dz);
      const rr = PLAYER.radius + COURT.ballRadius;
      if (d < rr && d > 0.001) {
        const nx = dx / d;
        const nz = dz / d;
        const speed = Math.hypot(b.vx, b.vz);
        b.x = p.x + nx * rr;
        b.z = p.z + nz * rr;
        if (speed > 4) {
          b.vx = nx * speed * 0.5 + p.vx * 0.5;
          b.vz = nz * speed * 0.5 + p.vz * 0.5;
          b.lastTouch = p.id;
          b.lastTeam = p.team;
          b.pickupLock = Math.min(b.pickupLock, 0.12);
        }
      }
    }
  }

  checkGoal() {
    const s = this.state;
    if (s.phase !== PHASE.playing) return;
    const b = s.ball;
    if (b.y > COURT.goalHeight - 0.06) return;
    if (Math.abs(b.z) > COURT.goalHalf - 0.03) return;
    if (b.x > COURT.halfL + 0.28) {
      this.scoreGoal(1);
    } else if (b.x < -COURT.halfL - 0.28) {
      this.scoreGoal(0);
    }
  }

  scoreGoal(teamScored) {
    const s = this.state;
    const touch = s.ball.lastTouch ? this.playerById(s.ball.lastTouch) : null;
    const ownGoal = touch && touch.team !== teamScored;
    let scorer = touch && touch.team === teamScored ? touch : this.closestToBall(teamScored);
    if (!scorer) scorer = s.players[teamScored * 5 + 4];
    if (ownGoal) scorer = touch;
    s.score[teamScored] += 1;
    s.lastGoalTeam = teamScored;
    s.lastScorer = { name: scorer.name, team: scorer.team, number: scorer.number, ownGoal: !!ownGoal };
    s.goalMinute = Math.max(1, Math.ceil((MATCH.halfSeconds - s.clock) / 60)) + (s.half - 1) * 3;
    s.phase = PHASE.goal;
    s.phaseT = MATCH.goalPause;
    s.ball.owner = null;
    s.ball.pickupLock = 10;
    s.ball.vx *= 0.2;
    s.ball.vz *= 0.2;
    s.ball.vy = Math.min(1.5, s.ball.vy);
    s.stats[teamScored].shots += 0;
    if (scorer.team === teamScored) scorer.goals += 1;
    for (const p of s.players) {
      if (p.team === teamScored) {
        p.action = ACTION.celebrate;
        p.actionT = 4;
      }
    }
    this.emit('goal', {
      team: teamScored,
      scorer: scorer.name,
      number: scorer.number,
      minute: s.goalMinute,
      ownGoal: !!ownGoal,
      score: [...s.score],
      ballX: s.ball.x,
      ballZ: s.ball.z,
    });
  }

  closestToBall(team) {
    return this.state.players
      .filter((p) => p.team === team)
      .sort((a, b) => Math.hypot(a.x - this.state.ball.x, a.z - this.state.ball.z) - Math.hypot(b.x - this.state.ball.x, b.z - this.state.ball.z))[0];
  }

  serialize() {
    const s = this.state;
    const players = s.players.map((p) => [
      Math.round(p.x * 100) / 100,
      Math.round(p.z * 100) / 100,
      Math.round(p.dir * 100) / 100,
      p.action,
      Math.round(p.actionT * 100) / 100,
      Math.round(p.stamina),
      Math.round((p.charge || 0) * 100) / 100,
    ]);
    return {
      t: Date.now(),
      ph: s.phase,
      pt: Math.round(s.phaseT * 10) / 10,
      cl: Math.round(s.clock * 10) / 10,
      h: s.half,
      sc: [...s.score],
      at: [...s.attacks],
      ap: [...s.active],
      b: [
        Math.round(s.ball.x * 100) / 100,
        Math.round(s.ball.y * 100) / 100,
        Math.round(s.ball.z * 100) / 100,
        Math.round(s.ball.vx * 100) / 100,
        Math.round(s.ball.vy * 100) / 100,
        Math.round(s.ball.vz * 100) / 100,
        s.ball.owner,
      ],
      p: players,
      st: s.stats,
      lg: s.lastGoalTeam,
      ls: s.lastScorer,
    };
  }

  applySnapshot(snap) {
    const s = this.state;
    s.phase = snap.ph;
    s.phaseT = snap.pt;
    s.clock = snap.cl;
    s.half = snap.h;
    s.score = snap.sc;
    s.attacks = snap.at;
    s.active = snap.ap;
    snap.p.forEach((v, i) => {
      const p = s.players[i];
      if (!p) return;
      p.x = v[0];
      p.z = v[1];
      p.dir = v[2];
      p.action = v[3];
      p.actionT = v[4];
      p.stamina = v[5];
      p.charge = v[6];
    });
    s.ball.x = snap.b[0];
    s.ball.y = snap.b[1];
    s.ball.z = snap.b[2];
    s.ball.vx = snap.b[3];
    s.ball.vy = snap.b[4];
    s.ball.vz = snap.b[5];
    s.ball.owner = snap.b[6];
    s.stats = snap.st;
    s.lastGoalTeam = snap.lg;
    s.lastScorer = snap.ls;
  }
}

function s2(p) {
  return p.action !== ACTION.slide;
}

