304:   loop(now) {
305:     requestAnimationFrame((t) => this.loop(t));
306:     const dt = Math.min(0.05, Math.max(0.001, (now - this.lastFrame) / 1000));
307:     this.lastFrame = now;
308:     if (!this.matchActive) {
309:       this.arena.updateMenu(dt, now, this.selectedIndex);
310:     } else if (this.state) {
311:       if (!this.paused) {
312:         if (this.mode === 'online-guest') {
313:           this.updateGuest(dt);
314:           this.sendGuestInput(now);
315:         } else if (this.sim) {
316:           const local = this.input.read();
317:           this.sim.setInput(0, local);
318:           if (this.mode === 'online-host') {
319:             this.sim.setInput(1, this.remoteInput);
320:             this.sendHostNetwork(now);
321:           }
322:           this.sim.update(dt);
323:         }
324:         this.arena.updateGame(this.state, dt, now, this.ownTeam);
325:         if (this.lastPhase !== this.state.phase) this.onPhaseChange(this.state.phase);
326:       } else {
327:         this.arena.updateGame(this.state, dt, now, this.ownTeam);
328:       }
329:       if (now - this.lastHud > 55) {
330:         this.lastHud = now;
331:         this.updateHUD();
332:       }
333:     }
334:     this.arena.render();
335:   }
336: 
337:   onPhaseChange(phase) {
338:     this.lastPhase = phase;
339:     if (phase === PHASE.halftime) {
340:       this.audio.halftime();
341:       this.addFeed('HALF TIME', 'استراحة قصيرة — تبديل المرمى');
342:       this.toast('نهاية الشوط الأول');
343:     } else if (phase === PHASE.fulltime) {
344:       this.finishMatch();
345:     } else if (phase === PHASE.playing) {
346:       this.audio.setExcitement(0.38);
347:     }
348:   }
349: 
350:   updateGuest(dt) {
351:     if (!this.guestSnapshot) return;
352:     const snap = this.guestSnapshot;
353:     const s = this.state;
354:     s.phase = snap.ph;
355:     s.phaseT = snap.pt;
356:     s.clock = snap.cl;
357:     s.half = snap.h;
358:     if (snap.sc[0] !== s.score[0] || snap.sc[1] !== s.score[1]) {
359:       s.score = [...snap.sc];
360:       this.updateScoreUI();
361:     }
362:     s.attacks = snap.at;
363:     s.active = snap.ap;
364:     s.stats = snap.st || s.stats;
365:     s.lastGoalTeam = snap.lg;
366:     s.lastScorer = snap.ls;
367:     const ease = 1 - Math.exp(-24 * dt);
368:     snap.p.forEach((v, i) => {
369:       const p = s.players[i];
370:       if (!p) return;
371:       p.x += (v[0] - p.x) * ease;
372:       p.z += (v[1] - p.z) * ease;
373:       p.vx = (v[0] - p.x) * 12;
374:       p.vz = (v[1] - p.z) * 12;
375:       p.dir = angleLerp(p.dir, v[2], 1 - Math.exp(-18 * dt));
376:       p.action = v[3];
377:       p.actionT = v[4];
378:       p.stamina = v[5];
379:       p.charge = v[6];
380:     });
381:     const b = snap.b;
382:     s.ball.x += (b[0] - s.ball.x) * Math.min(1, ease * 1.6);
383:     s.ball.y += (b[1] - s.ball.y) * Math.min(1, ease * 1.6);
384:     s.ball.z += (b[2] - s.ball.z) * Math.min(1, ease * 1.6);
385:     s.ball.vx = b[3];
386:     s.ball.vy = b[4];
387:     s.ball.vz = b[5];
388:     s.ball.owner = b[6];
389:   }
