391:   sendGuestInput(now) {
392:     if (!this.net || !this.net.connected || now - this.lastGuestSend < 45) return;
393:     this.lastGuestSend = now;
394:     const input = this.input.read();
395:     this.net.send({ type: 'input', input });
396:   }
397: 
398:   sendHostNetwork(now) {
399:     if (!this.net || !this.net.connected) return;
400:     if (now - this.lastNet < 50) return;
401:     this.lastNet = now;
402:     this.net.send({ type: 'snapshot', snap: this.sim.serialize() });
403:   }
404: 
405:   onSimEvent(type, data) {
406:     if (this.mode === 'online-host' && this.net?.connected && type !== 'kickoff') {
407:       this.net.send({ type: 'event', event: { type, data } });
408:     }
409:     this.handleEventVisual(type, data);
410:   }
411: 
412:   handleEventVisual(type, data) {
413:     if (type === 'goal') {
414:       this.showGoal(data);
415:       this.addFeed('GOAL', `${data.scorer} • ${data.minute}'`);
416:       this.updateScoreUI();
417:     } else if (type === 'shot') {
418:       this.audio.kick(data.power || 0.7);
419:       this.arena.addShake(0.018 + (data.power || 0.5) * 0.02);
420:       this.audio.setExcitement(0.85);
421:       setTimeout(() => this.audio.setExcitement(0.45), 900);
422:     } else if (type === 'pass') {
423:       this.audio.pass();
424:     } else if (type === 'tackle') {
425:       if (data.won) {
426:         this.audio.tackle();
427:         this.arena.addShake(0.02);
428:       }
429:     } else if (type === 'post') {
430:       this.audio.post();
431:       this.arena.addShake(0.12);
432:       this.addFeed('WOODWORK', 'الكرة على الخشبة!');
433:     } else if (type === 'wall') {
434:       this.audio.pass();
435:     } else if (type === 'countdown') {
436:       this.audio.countdown(data.n === 1);
437:     } else if (type === 'whistle') {
438:       this.audio.whistle();
439:     } else if (type === 'halftime') {
440:       this.audio.halftime();
441:       this.addFeed('HALF TIME', 'استراحة قصيرة — تبديل المرمى');
442:     } else if (type === 'fulltime') {
443:       this.finishMatch();
444:     } else if (type === 'secondhalf') {
445:       this.addFeed('SECOND HALF', 'تبديل المرمى — هيا!');
446:       this.audio.whistle();
447:     } else if (type === 'switch') {
448:       this.audio.click();
449:     }
450:   }
451: 
452:   showGoal(data) {
453:     const overlay = $('goal-overlay');
454:     const team = data.team === 0 ? this.homeTeam : this.awayTeam;
455:     $('goal-team').textContent = team.name;
456:     $('goal-player').textContent = data.ownGoal ? `OWN GOAL • ${data.scorer}` : data.scorer;
457:     $('goal-minute').textContent = `${data.minute}'`;
458:     $('goal-overlay').querySelector('.goal-content h2').style.color = team.color;
459:     overlay.classList.remove('active');
460:     // restart CSS animation
461:     void overlay.offsetWidth;
462:     overlay.classList.add('active', 'flash');
463:     this.audio.goal();
464:     this.arena.celebrate(data.team);
465:     this.arena.addShake(0.22);
466:     this.audio.setExcitement(1);
467:     clearTimeout(this.goalTimer);
468:     this.goalTimer = setTimeout(() => {
469:       overlay.classList.remove('active', 'flash');
470:       this.audio.setExcitement(0.4);
471:     }, 3800);
472:   }
473: 
474:   updateHUD() {
475:     const state = this.state;
476:     if (!state) return;
477:     this.updateScoreUI();
478:     const clock = Math.max(0, state.clock);
479:     const minutes = Math.floor(clock / 60);
480:     const seconds = Math.floor(clock % 60);
481:     $('clock').textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
482:     $('half-label').textContent = state.half === 1 ? 'H1' : 'H2';
483:     const team = this.ownTeam;
484:     const active = state.players.find((p) => p.id === state.active[team]) || state.players[team * 5 + 4];
485:     if (active) {
486:       $('player-num').textContent = active.number;
487:       $('player-name').textContent = active.name;
488:       $('player-role').textContent = ROLE_LABEL[active.role] || active.role;
489:       $('stamina-fill').style.width = `${active.stamina}%`;
490:       $('player-num').style.background = (active.team === 0 ? this.homeTeam : this.awayTeam).color;
491:     }
492:     const charge = active?.charge || 0;
493:     $('charge-wrap').classList.toggle('active', charge > 0.02);
494:     $('charge-fill').style.width = `${clamp(charge * 100, 0, 100)}%`;
495:     this.updateCountdown();
496:   }
497: 
498:   updateScoreUI() {
499:     if (!this.state) return;
500:     $('home-score').textContent = this.state.score[0];
501:     $('away-score').textContent = this.state.score[1];
502:     $('home-code').textContent = this.homeTeam.code;
503:     $('away-code').textContent = this.awayTeam.code;
504:     $('home-badge').textContent = this.homeTeam.initial;
505:     $('away-badge').textContent = this.awayTeam.initial;
506:     $('home-badge').style.background = this.homeTeam.color;
507:     $('away-badge').style.background = this.awayTeam.color;
508:     $('home-badge').style.color = this.homeTeam.ink;
509:     $('away-badge').style.color = this.awayTeam.ink;
510:   }
511: 
512:   updateCountdown() {
513:     const state = this.state;
514:     const overlay = $('countdown');
515:     if (!state || this.paused) {
516:       overlay.classList.remove('active');
517:       return;
518:     }
519:     if (state.phase === PHASE.countdown) {
520:       overlay.classList.add('active');
