227:   ctx.strokeStyle = 'rgba(20,40,44,.32)';
228:   ctx.lineWidth = 2;
229:   for (let x = 25; x < 512; x += 48) {
230:     ctx.beginPath();
231:     ctx.arc(x, 130, 40, 0.2, 2.5);
232:     ctx.stroke();
233:   }
234:   ctx.fillStyle = 'rgba(217,255,67,.9)';
235:   ctx.font = '700 17px Rajdhani, sans-serif';
236:   ctx.textAlign = 'center';
237:   ctx.fillText('KHAMASI', 256, 136);
238:   return canvasTexture(canvas, 8);
239: }
