264:   ctx.textAlign = 'center';
265:   ctx.letterSpacing = '14px';
266:   ctx.fillText('KHAMASI', 512, 105);
267:   ctx.fillStyle = '#dcebe4';
268:   ctx.font = '600 30px Cairo, sans-serif';
269:   ctx.letterSpacing = '4px';
270:   ctx.fillText(`${teamA.name}  ×  ${teamB.name}`, 512, 168);
271:   ctx.fillStyle = 'rgba(255,255,255,.36)';
272:   ctx.font = '500 18px Rajdhani, sans-serif';
273:   ctx.letterSpacing = '10px';
274:   ctx.fillText('FIVE-A-SIDE  •  NIGHT LEAGUE', 512, 216);
275:   return canvasTexture(canvas, 4);
276: }
