699:     const count = 260;
700:     const geo = new THREE.BufferGeometry();
701:     const positions = new Float32Array(count * 3);
702:     const colors = new Float32Array(count * 3);
703:     geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
704:     geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
705:     const mat = new THREE.PointsMaterial({ size: 0.13, vertexColors: true, transparent: true, opacity: 0, depthWrite: false });
706:     this.confetti = new THREE.Points(geo, mat);
707:     this.confetti.frustumCulled = false;
708:     this.scene.add(this.confetti);
709:     this.confettiData = [];
710:   }
