881:   updateMenu(dt, now, selectedTeam) {
882:     this.menuPhase += dt;
883:     const t = now * 0.00009;
884:     const bob = Math.sin(now * 0.00045);
885:     const target = new THREE.Vector3(0, 0.6, 0);
886:     const cam = new THREE.Vector3(
887:       Math.sin(t * 1.7 + 0.6) * 14.5,
888:       8.3 + bob * 0.35,
889:       18.5 + Math.cos(t * 1.25) * 3.5,
890:     );
891:     this.camera.position.lerp(cam, 1 - Math.exp(-1.5 * dt));
892:     this.cameraTarget.lerp(target, 1 - Math.exp(-1.6 * dt));
893:     this.camera.lookAt(this.cameraTarget);
894:     if (this.showcasePlayers) {
895:       for (const p of this.showcasePlayers) {
896:         const view = this.playerViews.get(p.id);
897:         if (!view) continue;
898:         const idx = p.index;
899:         const sway = Math.sin(now * 0.0011 + idx * 1.7) * 0.12;
900:         view.root.position.x = p.x;
901:         view.root.position.z = p.z;
902:         view.root.rotation.y = Math.PI / 2 - p.dir;
903:         view.body.position.y = Math.sin(now * 0.0018 + idx) * 0.008;
904:         view.leftArm.rotation.x = sway;
905:         view.rightArm.rotation.x = -sway;
906:         view.leftLeg.rotation.x = -sway * 0.6;
907:         view.rightLeg.rotation.x = sway * 0.6;
908:       }
909:       const ball = this.ball;
910:       ball.position.y = COURT.ballRadius + Math.abs(Math.sin(now * 0.0022)) * 0.35;
911:       ball.position.x = Math.sin(now * 0.0007) * 0.2;
912:       ball.rotation.z += dt * 0.7;
913:     }
914:     this.updateConfetti(dt);
915:     if (this.confetti) this.confetti.material.opacity = Math.max(0, this.confetti.material.opacity - dt * 0.7);
916:   }
