918:   updateGame(state, dt, now, ownTeam, cameraMode = 'game') {
919:     this.lastState = state;
920:     for (const p of state.players) {
921:       let view = this.playerViews.get(p.id);
922:       if (!view) {
923:         const team = p.team === 0 ? this.homeTeam : this.awayTeam;
924:         view = this.createPlayerView(p, team, p.role === 'GK', p.team === 0);
925:       }
926:       view.root.position.x = lerp(view.root.position.x, p.x, 1 - Math.exp(-26 * dt));
927:       view.root.position.z = lerp(view.root.position.z, p.z, 1 - Math.exp(-26 * dt));
928:       const wantedRot = Math.PI / 2 - p.dir;
929:       view.root.rotation.y = angleLerp(view.root.rotation.y, wantedRot, 1 - Math.exp(-16 * dt));
930:       const speed = Math.hypot(p.vx || 0, p.vz || 0);
931:       view.speed = lerp(view.speed, speed, 1 - Math.exp(-10 * dt));
932:       this.animatePlayer(view, p, dt, now);
933:       const controlled = state.active && state.active[p.team] === p.id && p.team === ownTeam;
934:       view.ring.visible = controlled;
935:       view.arrow.visible = controlled;
936:       if (controlled) {
937:         const pulse = 1 + Math.sin(now * 0.004) * 0.08;
938:         view.ring.scale.setScalar(pulse);
939:         view.arrow.position.y = 2.14 + Math.sin(now * 0.004) * 0.05;
940:       }
941:     }
942:     const ball = this.ball;
943:     ball.position.set(state.ball.x, state.ball.y, state.ball.z);
944:     ball.rotation.x += (state.ball.vz || 0) * dt * 3.1;
945:     ball.rotation.z -= (state.ball.vx || 0) * dt * 3.1;
946:     this.updateTrail(state, dt);
947:     this.updateConfetti(dt);
948:     this.updateCamera(state, dt, now, cameraMode);
949:     // crowd excitement drives ambient through CSS? handled by audio
950:   }
