952:   animatePlayer(view, p, dt, now) {
953:     const speed = view.speed || 0;
954:     const action = p.action || 0;
955:     const actionT = p.actionT || 0;
956:     const moving = speed > 0.35;
957:     const runSpeed = clamp(speed / 5.4, 0.25, 1.5);
958:     view.phase += dt * (moving ? 8 + runSpeed * 5 : 2.2);
959:     let swing = moving ? Math.sin(view.phase) * (0.48 + runSpeed * 0.2) : Math.sin(view.phase) * 0.025;
960:     let armSwing = moving ? -Math.sin(view.phase) * (0.38 + runSpeed * 0.18) : Math.sin(view.phase * 0.7) * 0.02;
961:     let bodyY = moving ? Math.abs(Math.sin(view.phase * 2)) * 0.022 : Math.sin(now * 0.002 + p.index) * 0.006;
962:     let lean = moving ? 0.08 + runSpeed * 0.055 : 0;
963:     let bodyRot = 0;
964:     let bodyZ = 0;
965:     view.body.position.y = bodyY;
966:     view.body.rotation.x = lean;
967:     view.body.rotation.z = 0;
968:     view.body.rotation.y = 0;
969:     view.root.position.y = 0;
970: 
971:     if (action === ACTION.kick || action === ACTION.shoot || action === ACTION.pass) {
972:       const kickPhase = Math.sin(clamp(1 - actionT / 0.28, 0, 1) * Math.PI);
973:       swing = kickPhase * 0.9;
974:       armSwing = -kickPhase * 0.7;
975:       bodyRot = kickPhase * 0.12;
976:     } else if (action === ACTION.slide) {
977:       const p2 = clamp(actionT / 0.55, 0, 1);
978:       view.root.position.y = 0.16 + p2 * 0.18;
979:       view.body.rotation.z = -1.02 + p2 * 0.15;
980:       view.body.rotation.x = -0.25;
981:       swing = 0.35;
982:       armSwing = 0.5;
983:     } else if (action === ACTION.dive) {
984:       const p2 = clamp(actionT / 0.55, 0, 1);
985:       view.root.position.y = 0.25;
986:       view.body.rotation.z = (p.goalSide || 1) * (-1.12 + p2 * 0.3);
987:       bodyZ = 0;
988:       swing = 0.4;
989:       armSwing = 0.85;
990:     } else if (action === ACTION.hurt) {
991:       view.body.rotation.z = 0.2;
992:       bodyY = 0.03;
993:     } else if (action === ACTION.celebrate) {
994:       const hop = Math.abs(Math.sin(now * 0.011 + p.index));
995:       view.root.position.y = hop * 0.28;
996:       view.body.rotation.x = -0.1;
997:       view.leftArm.rotation.x = Math.PI * 0.82;
998:       view.rightArm.rotation.x = Math.PI * 0.82;
999:       view.leftArm.rotation.z = -0.3;
1000:       view.rightArm.rotation.z = 0.3;
1001:       view.leftLeg.rotation.x = -0.2;
1002:       view.rightLeg.rotation.x = 0.2;
1003:       return;
1004:     }
1005:     view.leftLeg.rotation.x = swing;
1006:     view.rightLeg.rotation.x = -swing;
1007:     view.leftArm.rotation.x = armSwing;
1008:     view.rightArm.rotation.x = -armSwing;
1009:     view.leftArm.rotation.z = -0.12;
1010:     view.rightArm.rotation.z = 0.12;
1011:     view.body.rotation.y = bodyRot;
1012:     view.body.rotation.z = bodyZ;
1013:   }
