1015:   updateTrail(state, dt) {
1016:     const speed = Math.hypot(state.ball.vx || 0, state.ball.vz || 0) + Math.abs(state.ball.vy || 0);
1017:     this.ballTrailPositions.unshift(new THREE.Vector3(state.ball.x, state.ball.y, state.ball.z));
1018:     if (this.ballTrailPositions.length > 22) this.ballTrailPositions.pop();
1019:     const attr = this.trail.geometry.getAttribute('position');
1020:     this.ballTrailPositions.forEach((v, i) => {
1021:       attr.setXYZ(i, v.x, v.y, v.z);
1022:     });
1023:     for (let i = this.ballTrailPositions.length; i < 22; i += 1) {
1024:       const last = this.ballTrailPositions[this.ballTrailPositions.length - 1] || new THREE.Vector3();
1025:       attr.setXYZ(i, last.x, last.y, last.z);
1026:     }
1027:     attr.needsUpdate = true;
1028:     this.trail.material.opacity = lerp(this.trail.material.opacity, clamp((speed - 9) / 20, 0, 0.5), 0.2);
1029:   }
