1031:   updateCamera(state, dt, now, cameraMode) {
1032:     let camX;
1033:     let camY;
1034:     let camZ;
1035:     let lookX;
1036:     let lookY;
1037:     let lookZ;
1038:     const ball = state.ball;
1039:     if (state.phase === PHASE.goal) {
1040:       const side = state.lastGoalTeam === 0 ? 1 : -1;
1041:       camX = side * 13.6;
1042:       camY = 7.9;
1043:       camZ = ball.z * 0.3 + 9.5;
1044:       lookX = side * 19.7;
1045:       lookY = 0.8;
1046:       lookZ = ball.z * 0.3;
1047:       camY += Math.sin(now * 0.002) * 0.12;
1048:     } else if (state.phase === PHASE.halftime || state.phase === PHASE.fulltime) {
1049:       const t = now * 0.00008;
1050:       camX = Math.sin(t) * 9;
1051:       camY = 10.5;
1052:       camZ = 20.5;
1053:       lookX = 0;
1054:       lookY = 0;
1055:       lookZ = 0;
1056:     } else {
1057:       camX = clamp(ball.x * 0.5, -7.6, 7.6);
1058:       camY = 13.8 + clamp(Math.abs(ball.x) - 12, 0, 7) * 0.17;
1059:       camZ = 18.4;
1060:       lookX = lerp(ball.x * 0.62, 0, 0.2);
1061:       lookY = 0.6;
1062:       lookZ = ball.z * 0.3;
1063:     }
1064:     if (cameraMode === 'wide') {
1065:       camX = 0;
1066:       camY = 15.2;
1067:       camZ = 23.5;
1068:       lookX = 0;
1069:       lookY = 0.5;
1070:       lookZ = 0;
1071:     }
1072:     const damping = 1 - Math.exp(-3.5 * dt);
1073:     this.camera.position.x = lerp(this.camera.position.x, camX, damping);
1074:     this.camera.position.y = lerp(this.camera.position.y, camY, damping);
1075:     this.camera.position.z = lerp(this.camera.position.z, camZ, damping);
1076:     this.cameraTarget.x = lerp(this.cameraTarget.x, lookX, damping);
1077:     this.cameraTarget.y = lerp(this.cameraTarget.y, lookY, damping);
1078:     this.cameraTarget.z = lerp(this.cameraTarget.z, lookZ, damping);
1079:     if (this.shake > 0.001) {
1080:       this.shake *= Math.exp(-4.5 * dt);
1081:       this.camera.position.x += (Math.random() - 0.5) * this.shake;
1082:       this.camera.position.y += (Math.random() - 0.5) * this.shake * 0.5;
1083:     } else this.shake = 0;
1084:     this.camera.lookAt(this.cameraTarget);
1085:   }
1086: 
1087:   addShake(amount) {
1088:     this.shake = Math.min(0.5, this.shake + amount);
1089:   }
