1091:   celebrate(team) {
1092:     const side = team === 0 ? 1 : -1;
1093:     const origin = new THREE.Vector3(side * 18.5, 1.2, (Math.random() - 0.5) * 2);
1094:     this.confettiData = [];
1095:     const colors = [new THREE.Color(0xd9ff43), new THREE.Color(0x47f2d0), new THREE.Color(0xff705d), new THREE.Color(0xffffff)];
1096:     const positions = this.confetti.geometry.getAttribute('position');
1097:     const colorAttr = this.confetti.geometry.getAttribute('color');
1098:     for (let i = 0; i < 260; i += 1) {
1099:       positions.setXYZ(i, origin.x + (Math.random() - 0.5) * 2, origin.y + Math.random() * 2, origin.z + (Math.random() - 0.5) * 3);
1100:       const c = colors[i % colors.length];
1101:       colorAttr.setXYZ(i, c.r, c.g, c.b);
1102:       this.confettiData.push({
1103:         x: origin.x, y: origin.y + Math.random() * 2, z: origin.z + (Math.random() - 0.5) * 3,
1104:         vx: (Math.random() - 0.5) * 5 - side * Math.random() * 2,
1105:         vy: Math.random() * 6 + 2,
1106:         vz: (Math.random() - 0.5) * 8,
1107:       });
1108:     }
1109:     positions.needsUpdate = true;
1110:     colorAttr.needsUpdate = true;
1111:     this.confetti.material.opacity = 1;
1112:     this.shake = 0.22;
1113:     this.netPulse = 1;
1114:   }
1115: 
1116:   updateConfetti(dt) {
1117:     if (!this.confettiData || this.confetti.material.opacity <= 0) return;
1118:     const positions = this.confetti.geometry.getAttribute('position');
1119:     for (let i = 0; i < this.confettiData.length; i += 1) {
1120:       const p = this.confettiData[i];
1121:       p.vy -= 8.5 * dt;
1122:       p.x += p.vx * dt;
1123:       p.y += p.vy * dt;
1124:       p.z += p.vz * dt;
1125:       if (p.y < 0.1) {
1126:         p.y = 0.1;
1127:         p.vy *= -0.25;
1128:         p.vx *= 0.8;
1129:         p.vz *= 0.8;
1130:       }
1131:       positions.setXYZ(i, p.x, p.y, p.z);
1132:     }
1133:     positions.needsUpdate = true;
1134:     this.confetti.material.opacity = Math.max(0, this.confetti.material.opacity - dt * 0.22);
1135:   }
