const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find((item) => item.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});
let id = 0;
const pending = new Map();
const runtimeErrors = [];
ws.onmessage = ({ data }) => {
  const msg = JSON.parse(data);
  if (msg.method === 'Runtime.exceptionThrown') runtimeErrors.push(msg.params.exceptionDetails.text);
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') runtimeErrors.push(msg.params.args.map((x) => x.value || x.description).join(' '));
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
  }
};
function call(method, params = {}) {
  const requestId = ++id;
  ws.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => pending.set(requestId, { resolve, reject }));
}
async function evaluate(expression, awaitPromise = false) {
  const result = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
  return result.result?.value;
}
async function screenshot(path) {
  const shot = await call('Page.captureScreenshot', { format: 'jpeg', quality: 72, captureBeyondViewport: false });
  await (await import('node:fs/promises')).writeFile(path, Buffer.from(shot.data, 'base64'));
}
await call('Page.enable');
await call('Runtime.enable');
await call('Emulation.setDeviceMetricsOverride', { width: 960, height: 600, deviceScaleFactor: 1, mobile: false });
await call('Page.navigate', { url: 'http://127.0.0.1:3002/' });
await evaluate('new Promise(resolve => setTimeout(resolve, 6000))', true);
console.log('MENU', JSON.stringify(await evaluate(`({title:document.title, menu:document.querySelector('#menu')?.className, teams:document.querySelectorAll('.team-dot').length, canvas:document.querySelector('#arena')?.clientWidth, gl:!!document.querySelector('#arena')?.getContext('webgl2')})`)));
await evaluate(`document.querySelector('#play-quick').click()`);
await evaluate('new Promise(resolve => setTimeout(resolve, 1300))', true);
console.log('MATCH', JSON.stringify(await evaluate(`({menu:document.querySelector('#menu')?.className,hud:document.querySelector('#hud')?.className,topbar:document.querySelector('#topbar')?.className,clock:document.querySelector('#clock')?.textContent,score:document.querySelector('#home-score')?.textContent+'-'+document.querySelector('#away-score')?.textContent,phase:document.querySelector('#countdown')?.className})`)));
await screenshot('/tmp/opencode/khamasi-match.jpg');
console.log('ERRORS', JSON.stringify(runtimeErrors));
ws.close();

