await wait(7000);
const before = await evaluate(`(() => { const a=window.__gameApp; const s=a.state; const p=s.players.find(x=>x.id===s.active[a.ownTeam]); return {phase:s.phase,clock:s.clock,team:a.ownTeam,active:s.active[a.ownTeam],player:{x:p.x,z:p.z,vx:p.vx,vz:p.vz,moveX:p.moveX,moveZ:p.moveZ},input:a.input.read()}; })()`);
await call('Input.dispatchKeyEvent', { type: 'keyDown', key: 'd', code: 'KeyD', windowsVirtualKeyCode: 68 });
await call('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Shift', code: 'ShiftLeft', windowsVirtualKeyCode: 16 });
await wait(1400);
const moving = await evaluate(`(() => { const a=window.__gameApp; const s=a.state; const p=s.players.find(x=>x.id===s.active[a.ownTeam]); return {phase:s.phase,clock:s.clock,active:s.active[a.ownTeam],player:{x:p.x,z:p.z,vx:p.vx,vz:p.vz,moveX:p.moveX,moveZ:p.moveZ},input:a.input.isDown()}; })()`);
